"use client"

import {
  useEffect,
  useRef,
  useState,
  useCallback,
  useMemo,
  useSyncExternalStore,
} from "react"
import maplibregl, {
  type ExpressionSpecification,
  type GeoJSONSource,
} from "maplibre-gl"
import "maplibre-gl/dist/maplibre-gl.css"
import { cn } from "@/lib/utils"
import { mapLineColorForBasemap } from "@/lib/tfl/dark-line-colours"
import type {
  TrackModel,
  TransitGeometryBundle,
  TransitMode,
} from "@/lib/tfl/geography-types"
import {
  TRANSIT_GEOMETRY_PUBLIC_ASSETS,
  openFreeMapStyleUrl,
  OSM_TRANSIT_GEOMETRY_CREDIT,
  transitGeometryAssetUrl,
  type TransitGeometryMode,
} from "@/lib/tfl/geography-credits"
import { useVehicleSegmentSource } from "@/components/tfl/geography/sync-vehicle-source"
import { provideMissingStyleImages } from "@/components/tfl/maps/provide-missing-style-images"
import {
  vehiclesToSegmentGeoJSON,
  type VehiclePosition,
} from "@/lib/tfl/map-vehicles"
import type { RoutePolyline } from "@/lib/tfl/vehicle-progress"

const LONDON_CENTER: [number, number] = [-0.12, 51.51]
const LONDON_ZOOM = 10.2

/** Bottom → top paint order so DLR / tram / Overground stay visible over Tube casing. */
const DEFAULT_MODES: readonly TransitMode[] = [
  "tube",
  "overground",
  "elizabeth",
  "dlr",
  "tram",
]

type TflGeographicMapProps = {
  /**
   * Pre-loaded geometry bundles keyed by mode. When omitted the component
   * fetches vendored GeoJSON from `/data/geography/`.
   */
  data?: Partial<Record<TransitMode, TransitGeometryBundle>>
  /** Which transit modes to render. Defaults to all five. */
  modes?: readonly TransitMode[]
  /** When set, only these line ids are painted. */
  lineIds?: readonly string[]
  /**
   * Unique-track layer to fetch when `data` is omitted.
   * `"centreline"` merges directional twins; `"dual"` keeps both tracks.
   */
  trackModel?: TrackModel
  /** Live vehicles. Positions are derived by the caller; this map paints track segments. */
  vehicles?: readonly VehiclePosition[]
  /**
   * Hop-indexed unique-track polylines used to paint and coast vehicles.
   * When omitted, the map falls back to whole-line unique-track features.
   */
  vehiclePolylines?: readonly RoutePolyline[]
  /** Keep vehicles walking along the track between arrival snapshots. */
  coast?: boolean
  /** Show station circles and names. Default true. */
  showStations?: boolean
  /** Show line tracks. Default true. */
  showLines?: boolean
  /** Show zoom/pan controls. Default true. */
  showNavigation?: boolean
  /** Initial center [lng, lat]. Default London. */
  center?: [number, number]
  /** Initial zoom level. Default 10.2. */
  zoom?: number
  className?: string
}

const subscribeDocumentDark = (onStoreChange: () => void) => {
  const observer = new MutationObserver(onStoreChange)
  observer.observe(document.documentElement, {
    attributes: true,
    attributeFilter: ["class"],
  })
  return () => observer.disconnect()
}

const getDocumentDark = () =>
  document.documentElement.classList.contains("dark")

const useDocumentDark = () =>
  useSyncExternalStore(subscribeDocumentDark, getDocumentDark, () => false)

const STATION_FILL = { light: "#ffffff", dark: "#111827" } as const
const STATION_STROKE = { light: "#111827", dark: "#ffffff" } as const
const LINE_CASING = { light: "#ffffff", dark: "#111827" } as const

const asFeatureCollection = (
  collection: TransitGeometryBundle["lines"] | TransitGeometryBundle["stations"]
) => ({
  type: "FeatureCollection" as const,
  features: collection.features ?? [],
})

const remapLineCollection = (
  collection: TransitGeometryBundle["lines"],
  dark: boolean
) => ({
  type: "FeatureCollection" as const,
  features: (collection.features ?? []).map((feature) => {
    const props = feature.properties
    if (!props?.color) return feature
    const next = mapLineColorForBasemap(props.color, dark)
    return {
      ...feature,
      properties: { ...props, color: next },
    }
  }),
})

const LINE_LAYOUT = {
  "line-join": "round" as const,
  "line-cap": "round" as const,
}

const VEHICLE_LAYOUT = {
  "line-join": "bevel" as const,
  "line-cap": "butt" as const,
}

const LINE_WIDTH: ExpressionSpecification = [
  "interpolate",
  ["linear"],
  ["zoom"],
  10,
  2.2,
  14,
  3.8,
  16,
  5,
]

const LINE_INNER_WIDTH: ExpressionSpecification = [
  "interpolate",
  ["linear"],
  ["zoom"],
  10,
  1.4,
  14,
  2.6,
  16,
  3.4,
]

const STATION_RADIUS: ExpressionSpecification = [
  "interpolate",
  ["linear"],
  ["zoom"],
  10,
  2.5,
  14,
  4,
  16,
  5,
]

const VEHICLE_LINE_WIDTH: ExpressionSpecification = [
  "interpolate",
  ["linear"],
  ["zoom"],
  10,
  ["*", 5.5, ["coalesce", ["get", "widthScale"], 1]],
  14,
  ["*", 9, ["coalesce", ["get", "widthScale"], 1]],
  16,
  ["*", 12, ["coalesce", ["get", "widthScale"], 1]],
]

const VEHICLE_LINE_OFFSET: ExpressionSpecification = [
  "interpolate",
  ["linear"],
  ["zoom"],
  10,
  -2,
  14,
  -3.5,
  16,
  -5,
]

const STATION_LABEL_SIZE: ExpressionSpecification = [
  "interpolate",
  ["linear"],
  ["zoom"],
  10,
  10,
  12,
  10,
  14,
  11,
  16,
  12,
]

/**
 * OpenFreeMap Positron paints OSM railways and neighbourhood names that fight
 * TfL corridors / station labels. Hide those so unique-track geometry wins.
 */
const OSM_LAYERS_TO_HIDE = [
  "railway_transit",
  "railway_transit_dashline",
  "railway_service",
  "railway_service_dashline",
  "railway",
  "railway_dashline",
  "label_other",
] as const

const prepareBasemapForTransit = (map: maplibregl.Map) => {
  for (const id of OSM_LAYERS_TO_HIDE) {
    if (map.getLayer(id)) {
      map.setLayoutProperty(id, "visibility", "none")
    }
  }
}

/**
 * Add sources first, then casings, then coloured cores, then stations + names.
 * Per-mode casing→core→stations stacks the next mode’s white casing over the
 * previous mode’s colour (Tube/Jubilee was hiding DLR teal in Docklands).
 */
const filterBundleLines = (
  bundle: TransitGeometryBundle,
  lineIds: readonly string[] | undefined
): TransitGeometryBundle["lines"] => {
  if (!lineIds?.length) return bundle.lines
  const allow = new Set(lineIds)
  return {
    type: "FeatureCollection",
    features: (bundle.lines.features ?? []).filter((feature) =>
      allow.has(feature.properties?.lineId ?? "")
    ),
  }
}

const filterBundleStations = (
  bundle: TransitGeometryBundle,
  lineIds: readonly string[] | undefined
): TransitGeometryBundle["stations"] => {
  if (!lineIds?.length) return bundle.stations
  const allow = new Set(lineIds)
  return {
    type: "FeatureCollection",
    features: (bundle.stations.features ?? []).filter((feature) =>
      (feature.properties?.lineIds ?? []).some((id) => allow.has(id))
    ),
  }
}

const polylinesFromBundles = (
  bundles: { mode: TransitGeometryMode; bundle: TransitGeometryBundle }[],
  lineIds?: readonly string[]
): RoutePolyline[] => {
  const allow = lineIds?.length ? new Set(lineIds) : null
  const out: RoutePolyline[] = []
  for (const { bundle } of bundles) {
    for (const feature of bundle.lines.features ?? []) {
      const lineId = feature.properties?.lineId ?? ""
      if (allow && !allow.has(lineId)) continue
      if (feature.geometry?.type === "LineString") {
        out.push({ lineId, line: feature.geometry })
      }
    }
  }
  return out
}

const fitLineBounds = (
  map: maplibregl.Map,
  bundles: { mode: TransitGeometryMode; bundle: TransitGeometryBundle }[],
  lineIds: readonly string[] | undefined
) => {
  if (!lineIds?.length) return
  const bounds = new maplibregl.LngLatBounds()
  let any = false
  for (const { bundle } of bundles) {
    for (const feature of filterBundleLines(bundle, lineIds).features ?? []) {
      if (feature.geometry?.type !== "LineString") continue
      for (const coord of feature.geometry.coordinates) {
        const lon = coord[0]
        const lat = coord[1]
        if (lon == null || lat == null) continue
        bounds.extend([lon, lat])
        any = true
      }
    }
  }
  if (any) map.fitBounds(bounds, { padding: 48, duration: 0 })
}

const addTransitLayers = (
  map: maplibregl.Map,
  bundles: { mode: TransitGeometryMode; bundle: TransitGeometryBundle }[],
  showLines: boolean,
  showStations: boolean,
  dark: boolean,
  lineIds?: readonly string[]
) => {
  const tone = dark ? "dark" : "light"

  for (const { mode, bundle } of bundles) {
    if (showLines) {
      map.addSource(`${mode}-lines`, {
        type: "geojson",
        data: remapLineCollection(filterBundleLines(bundle, lineIds), dark),
      })
    }
    if (showStations) {
      map.addSource(`${mode}-stations`, {
        type: "geojson",
        data: asFeatureCollection(filterBundleStations(bundle, lineIds)),
      })
    }
  }

  if (showLines) {
    for (const { mode } of bundles) {
      map.addLayer({
        id: `${mode}-lines-casing`,
        type: "line",
        source: `${mode}-lines`,
        layout: LINE_LAYOUT,
        paint: {
          "line-color": LINE_CASING[tone],
          "line-width": LINE_WIDTH,
          "line-opacity": 0.92,
        },
      })
    }
    for (const { mode } of bundles) {
      map.addLayer({
        id: `${mode}-lines-core`,
        type: "line",
        source: `${mode}-lines`,
        layout: LINE_LAYOUT,
        paint: {
          "line-color": [
            "coalesce",
            ["get", "color"],
            ["get", "lineColour"],
            "#0019A8",
          ],
          "line-width": LINE_INNER_WIDTH,
        },
      })
    }
  }

  if (showStations) {
    for (const { mode } of bundles) {
      map.addLayer({
        id: `${mode}-stations`,
        type: "circle",
        source: `${mode}-stations`,
        minzoom: 10,
        paint: {
          "circle-radius": STATION_RADIUS,
          "circle-color": STATION_FILL[tone],
          "circle-stroke-width": 1.4,
          "circle-stroke-color": STATION_STROKE[tone],
          "circle-opacity": 0.98,
        },
      })
    }
    for (const { mode } of bundles) {
      map.addLayer({
        id: `${mode}-stations-label`,
        type: "symbol",
        source: `${mode}-stations`,
        minzoom: 10,
        layout: {
          "text-field": ["coalesce", ["get", "label"], ["get", "name"], ""],
          "text-font": ["Noto Sans Regular"],
          "text-size": STATION_LABEL_SIZE,
          "text-offset": [0, 1.15],
          "text-anchor": "top",
          "text-max-width": 8,
          "text-allow-overlap": false,
          "text-optional": true,
          "text-padding": 2,
        },
        paint: {
          "text-color": STATION_STROKE[tone],
          "text-halo-color": STATION_FILL[tone],
          "text-halo-width": 1.6,
        },
      })
    }
  }

  if (!map.getSource("rail-vehicles")) {
    map.addSource("rail-vehicles", {
      type: "geojson",
      data: vehiclesToSegmentGeoJSON([], []),
    })
    map.addLayer({
      id: "rail-vehicles",
      type: "line",
      source: "rail-vehicles",
      layout: VEHICLE_LAYOUT,
      paint: {
        "line-color": dark ? "#9ca3af" : "#4b5563",
        "line-width": VEHICLE_LINE_WIDTH,
        "line-offset": VEHICLE_LINE_OFFSET,
        "line-opacity": 0.96,
      },
    })
  }
}

/**
 * Free geographic map — MapLibre GL JS over OpenFreeMap Positron / Dark.
 * No API key. Station names render from the geometry `label` / `name` fields.
 *
 * Renders unique-track OSM transit geometry by default (merged centreline,
 * not every timetable variant). Pass `trackModel="dual"` for both
 * directional tracks. Fetches from `/data/geography/`. Auto-fills parent
 * via `h-full w-full`.
 *
 * ```tsx
 * <div className="h-100">
 *   <TflGeographicMap />
 * </div>
 * ```
 */
export const TflGeographicMap = ({
  data,
  modes,
  lineIds,
  trackModel = "centreline",
  vehicles,
  vehiclePolylines,
  coast = false,
  showStations = true,
  showLines = true,
  showNavigation = true,
  center = LONDON_CENTER,
  zoom = LONDON_ZOOM,
  className,
}: TflGeographicMapProps) => {
  const containerRef = useRef<HTMLDivElement | null>(null)
  const mapRef = useRef<maplibregl.Map | null>(null)
  const bundlesRef = useRef<
    { mode: TransitGeometryMode; bundle: TransitGeometryBundle }[] | null
  >(null)
  const skipStyleSwapRef = useRef(true)
  const fittedRef = useRef(false)
  const trackModelRef = useRef(trackModel)
  const lineIdsKey = lineIds?.join(",") ?? ""
  const modesKey = (modes ?? DEFAULT_MODES).join(",")
  const dark = useDocumentDark()
  const [status, setStatus] = useState<"loading" | "ready" | "error">("loading")

  const activeModes = useMemo(
    () => modes ?? DEFAULT_MODES,
    // Parent arrays are often inline (`modes={["tube"]}`); compare by id list.
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [modesKey]
  )

  const loadGeometry = useCallback(async (): Promise<
    { mode: TransitGeometryMode; bundle: TransitGeometryBundle }[]
  > => {
    if (data) {
      const ordered = DEFAULT_MODES.filter(
        (mode) => activeModes.includes(mode) && data[mode]
      )
      return ordered.map((mode) => ({
        mode,
        bundle: data[mode] as TransitGeometryBundle,
      }))
    }

    const assetByMode = new Map(
      TRANSIT_GEOMETRY_PUBLIC_ASSETS.map((asset) => [asset.mode, asset])
    )
    const orderedModes = DEFAULT_MODES.filter((mode) =>
      activeModes.includes(mode)
    )

    const results = await Promise.all(
      orderedModes.map(async (mode) => {
        const asset = assetByMode.get(mode)
        if (!asset) {
          throw new Error(`No geography asset for mode ${mode}`)
        }
        const url = transitGeometryAssetUrl(mode, trackModel)
        const res = await fetch(url)
        if (!res.ok) {
          throw new Error(`Failed to load ${asset.label} (${res.status})`)
        }
        return {
          mode,
          bundle: (await res.json()) as TransitGeometryBundle,
        }
      })
    )
    return results
  }, [data, activeModes, trackModel])

  const loadGeometryRef = useRef(loadGeometry)
  loadGeometryRef.current = loadGeometry
  const vehiclePolylinesRef = useRef(vehiclePolylines)
  vehiclePolylinesRef.current = vehiclePolylines

  const getPolylines = useCallback(
    (): RoutePolyline[] => {
      const hops = vehiclePolylinesRef.current
      if (hops && hops.length > 0) return [...hops]
      return polylinesFromBundles(bundlesRef.current ?? [], lineIds)
    },
    // lineIds identity is represented by lineIdsKey.
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [lineIdsKey]
  )

  const { flush: flushVehicles } = useVehicleSegmentSource({
    mapRef,
    sourceId: "rail-vehicles",
    vehicles,
    getPolylines,
    coast,
    ready: status === "ready",
  })

  useEffect(() => {
    const container = containerRef.current
    if (!container || mapRef.current) return

    let cancelled = false

    const map = new maplibregl.Map({
      container,
      style: openFreeMapStyleUrl(dark),
      center,
      zoom,
      attributionControl: { compact: true },
      cooperativeGestures: true,
    })
    provideMissingStyleImages(map)

    if (showNavigation) {
      map.addControl(
        new maplibregl.NavigationControl({ showCompass: false }),
        "top-right"
      )
    }
    mapRef.current = map

    map.on("load", async () => {
      try {
        prepareBasemapForTransit(map)
        const bundles = bundlesRef.current ?? (await loadGeometryRef.current())
        if (cancelled) return
        bundlesRef.current = bundles

        addTransitLayers(map, bundles, showLines, showStations, dark, lineIds)
        if (!fittedRef.current) {
          fitLineBounds(map, bundles, lineIds)
          fittedRef.current = true
        }
        setStatus("ready")
      } catch {
        if (!cancelled) setStatus("error")
      }
    })

    return () => {
      cancelled = true
      map.remove()
      mapRef.current = null
    }
    // Create once. Overlay and style swaps live in the effects below.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [showNavigation])

  useEffect(() => {
    const map = mapRef.current
    if (!map) return
    if (skipStyleSwapRef.current) {
      skipStyleSwapRef.current = false
      return
    }

    const applyOverlays = () => {
      const bundles = bundlesRef.current
      if (!bundles) return
      prepareBasemapForTransit(map)
      addTransitLayers(map, bundles, showLines, showStations, dark, lineIds)
      flushVehicles()
    }

    map.setStyle(openFreeMapStyleUrl(dark))
    map.once("style.load", applyOverlays)
    return () => {
      map.off("style.load", applyOverlays)
    }
  }, [dark, showLines, showStations, lineIdsKey, flushVehicles])

  useEffect(() => {
    if (data) return
    const map = mapRef.current
    if (!map || status !== "ready") return
    if (trackModelRef.current === trackModel) return
    trackModelRef.current = trackModel

    let cancelled = false
    const applyTrackModel = async () => {
      try {
        const bundles = await loadGeometry()
        if (cancelled || !mapRef.current) return
        bundlesRef.current = bundles
        for (const { mode, bundle } of bundles) {
          const source = map.getSource(`${mode}-lines`) as
            GeoJSONSource | undefined
          source?.setData(
            remapLineCollection(filterBundleLines(bundle, lineIds), dark)
          )
        }
        flushVehicles()
      } catch {
        if (!cancelled) setStatus("error")
      }
    }
    void applyTrackModel()
    return () => {
      cancelled = true
    }
  }, [trackModel, status, data, loadGeometry, dark, lineIds, flushVehicles])

  return (
    <div
      ref={containerRef}
      className={cn("h-full w-full bg-muted", className)}
      role="region"
      aria-label="TfL geographic transit map"
      aria-busy={status === "loading"}
    >
      {status === "error" && (
        <div className="flex h-full items-center justify-center p-4 text-sm text-muted-foreground">
          Failed to load geometry.{" "}
          <span className="sr-only">
            {OSM_TRANSIT_GEOMETRY_CREDIT.attribution}
          </span>
        </div>
      )}
    </div>
  )
}

import type { Map as MapLibreMap } from "maplibre-gl"

const WOOD_PATTERN_ID = "wood-pattern"
const WOOD_PIXEL = new Uint8Array([32, 32, 32, 255])
const EMPTY_PIXEL = new Uint8Array(4)

/**
 * OpenFreeMap dark style paints woods with `fill-pattern: wood-pattern`,
 * but that image is not in the published sprite. Supply a 1×1 stand-in so
 * MapLibre does not warn; any other missing sprite gets a transparent pixel.
 */
export const provideMissingStyleImages = (map: MapLibreMap) => {
  map.on("styleimagemissing", (event) => {
    if (map.hasImage(event.id)) return
    map.addImage(event.id, {
      width: 1,
      height: 1,
      data: new Uint8Array(
        event.id === WOOD_PATTERN_ID ? WOOD_PIXEL : EMPTY_PIXEL
      ),
    })
  })
}

/**
 * Credits for geographic datasets vendored under data/geography.
 * Keep in sync with data/geography/ORIGIN.md.
 */
import type { TrackModel } from "@/lib/tfl/geography-types"

export type GeographyCredit = {
  id: string
  title: string
  provider: string
  licence: string
  licenceUrl: string
  datasetUrl: string
  attribution: string
  notes?: string
}

export type TransitGeometryMode =
  "tube" | "elizabeth" | "overground" | "dlr" | "tram"

export type TransitGeometryPublicAsset = {
  mode: TransitGeometryMode
  label: string
  url: `/data/geography/${string}`
}

export const transitGeometryAssetUrl = (
  mode: TransitGeometryMode,
  model: TrackModel = "centreline"
): `/data/geography/${string}` =>
  model === "dual"
    ? `/data/geography/${mode}-geometry-dual.json`
    : `/data/geography/${mode}-geometry.json`

export const transitGraphAssetUrl = (
  mode: TransitGeometryMode
): `/data/geography/${string}` => `/data/geography/${mode}-graph.json`

/**
 * Unique-track GeoJSON served under `/data/geography/` for map drawing
 * (merged centreline). Dual and graph URLs are `transitGeometryAssetUrl`
 * / `transitGraphAssetUrl`. Order = bottom → top paint preference.
 * Rebuild with `pnpm geography:unique-track`.
 */
export const TRANSIT_GEOMETRY_PUBLIC_ASSETS: readonly TransitGeometryPublicAsset[] =
  [
    {
      mode: "tube",
      label: "Underground",
      url: transitGeometryAssetUrl("tube"),
    },
    {
      mode: "overground",
      label: "Overground",
      url: transitGeometryAssetUrl("overground"),
    },
    {
      mode: "elizabeth",
      label: "Elizabeth line",
      url: transitGeometryAssetUrl("elizabeth"),
    },
    {
      mode: "dlr",
      label: "DLR",
      url: transitGeometryAssetUrl("dlr"),
    },
    {
      mode: "tram",
      label: "Tram",
      url: transitGeometryAssetUrl("tram"),
    },
  ] as const

export const TRANSIT_GEOMETRY_DUAL_ASSETS: readonly TransitGeometryPublicAsset[] =
  TRANSIT_GEOMETRY_PUBLIC_ASSETS.map((asset) => ({
    ...asset,
    url: transitGeometryAssetUrl(asset.mode, "dual"),
  }))

export const TRANSIT_GEOMETRY_GRAPH_ASSETS: readonly {
  mode: TransitGeometryMode
  label: string
  url: `/data/geography/${string}`
}[] = TRANSIT_GEOMETRY_PUBLIC_ASSETS.map((asset) => ({
  mode: asset.mode,
  label: asset.label,
  url: transitGraphAssetUrl(asset.mode),
}))

export const OSM_TRANSIT_GEOMETRY_CREDIT: GeographyCredit = {
  id: "osm-transit-geometry",
  title: "OpenStreetMap London transit route geometry",
  provider: "OpenStreetMap contributors",
  licence: "ODbL 1.0",
  licenceUrl: "https://opendatacommons.org/licenses/odbl/1-0/",
  datasetUrl: "https://www.openstreetmap.org/copyright",
  attribution: "© OpenStreetMap contributors · track geometry · ODbL",
  notes:
    "Unique-track map layers (merged centreline, dual directional tracks, welded junction graph) derived from ssh.ldn Overpass cache. Full route variants stay under data/geography for non-map use.",
}

export const TFL_STATION_ENRICHMENT_CREDIT: GeographyCredit = {
  id: "tfl-station-enrichment",
  title: "TfL station metadata (enrichment)",
  provider: "Transport for London",
  licence: "TfL Open Data",
  licenceUrl: "https://tfl.gov.uk/info-for/open-data-users/",
  datasetUrl: "https://api.tfl.gov.uk/",
  attribution: "© Transport for London · station metadata where present",
}

/** Vector Positron — same OpenFreeMap style ssh.ldn uses instead of CARTO PNG rasters. */
export const OPENFREEMAP_POSITRON_STYLE_URL =
  "https://tiles.openfreemap.org/styles/positron" as const

/** OpenFreeMap dark — pair to Positron for theme-aware maps. */
export const OPENFREEMAP_DARK_STYLE_URL =
  "https://tiles.openfreemap.org/styles/dark" as const

export const openFreeMapStyleUrl = (dark: boolean): string =>
  dark ? OPENFREEMAP_DARK_STYLE_URL : OPENFREEMAP_POSITRON_STYLE_URL

export const OPENFREEMAP_BASEMAP_CREDIT: GeographyCredit = {
  id: "openfreemap-positron",
  title: "OpenFreeMap Positron basemap",
  provider: "OpenFreeMap · OpenMapTiles · OpenStreetMap contributors",
  licence: "BSD / ODbL (OSM data)",
  licenceUrl: "https://openfreemap.org/",
  datasetUrl: "https://tiles.openfreemap.org/",
  attribution: "© OpenStreetMap contributors · © OpenFreeMap",
}

import type { FeatureCollection, LineString, Point } from "geojson"
import { hopGraphForRailLine } from "@/lib/tfl/vehicle-hop-graph"
import {
  orientLineToBearing,
  segmentAroundPoint,
  vehicleLengthMeters,
  vehicleStrokeScale,
  type RoutePolyline,
} from "@/lib/tfl/vehicle-progress"

export type VehiclePosition = {
  vehicleId: string
  lineId: string
  lat: number
  lon: number
  bearingDeg: number
  destinationName: string
  timeToNextStationSec: number
  /** Paint colour for the map marker. Set by the caller. */
  color?: string
  /** Override {@link vehicleLengthMeters} for this vehicle. */
  lengthMeters?: number
  /** Epoch ms when `timeToStation` values were read. */
  asOf?: number
  /** The stop this vehicle is next due at — coasting re-places it here as `timeToNextStationSec` counts down. */
  nextStopLat?: number
  nextStopLon?: number
  /** The stop after that, used only to pick which way is "backward" along the track. */
  followingStopLat?: number
  followingStopLon?: number
  /** Naptan of the locked next stop. */
  nextStopId?: string
  /** Naptan of the hop's previous stop, when known. */
  fromStopId?: string
  /** Remaining km to `nextStop`. Drains while coasting; never increases on a locked hop. */
  remainingKm?: number
  /** Epoch ms when this hop's remaining km first hit 0. */
  arrivedAtMs?: number
}

export type VehiclePointProperties = {
  vehicleId: string
  lineId: string
  destinationName: string
  bearingDeg: number
  color: string
}

export type VehicleSegmentProperties = {
  vehicleId: string
  lineId: string
  destinationName: string
  widthScale: number
}

export const vehiclesToGeoJSON = (
  vehicles: readonly VehiclePosition[]
): FeatureCollection<Point, VehiclePointProperties> => ({
  type: "FeatureCollection",
  features: vehicles
    .filter(
      (vehicle) => Number.isFinite(vehicle.lat) && Number.isFinite(vehicle.lon)
    )
    .map((vehicle) => ({
      type: "Feature",
      id: vehicle.vehicleId,
      properties: {
        vehicleId: vehicle.vehicleId,
        lineId: vehicle.lineId,
        destinationName: vehicle.destinationName,
        bearingDeg: vehicle.bearingDeg,
        color: vehicle.color ?? "#0019A8",
      },
      geometry: {
        type: "Point",
        coordinates: [vehicle.lon, vehicle.lat],
      },
    })),
})

export const vehiclesToSegmentGeoJSON = (
  vehicles: readonly VehiclePosition[],
  polylines: readonly RoutePolyline[]
): FeatureCollection<LineString, VehicleSegmentProperties> => ({
  type: "FeatureCollection",
  features: vehicles
    .filter(
      (vehicle) => Number.isFinite(vehicle.lat) && Number.isFinite(vehicle.lon)
    )
    .map((vehicle) => ({
      type: "Feature",
      id: vehicle.vehicleId,
      properties: {
        vehicleId: vehicle.vehicleId,
        lineId: vehicle.lineId,
        destinationName: vehicle.destinationName,
        widthScale: vehicleStrokeScale(vehicle.lineId),
      },
      geometry: orientLineToBearing(
        segmentAroundPoint({
          at: { lat: vehicle.lat, lon: vehicle.lon },
          lengthMeters:
            vehicle.lengthMeters ?? vehicleLengthMeters(vehicle.lineId),
          lineId: vehicle.lineId,
          polylines,
          fromStopId: vehicle.fromStopId,
          toStopId: vehicle.nextStopId,
          canonical: hopGraphForRailLine(vehicle.lineId).canonical,
        }),
        vehicle.bearingDeg
      ),
    })),
})

/**
 * Dark-map line colours derived from TfL Go day→night research.
 *
 * Default dark palette = Issue-4 brand OKLCH + capture-resistant median
 * day→night delta (raise L, slight C, hold hue). Northern is the Go-style
 * light fill (`#FCFCFC`), not brand black.
 *
 * Opt-in halo: keep brand-black Northern with a light stroke / text-shadow
 * via `data-tfl-northern="halo"` (see generated `tfl-colours.css`).
 */

import type { BrandColourSpec } from "@/lib/tfl/brand-colours"
import {
  parseHex,
  parseRgbChannels,
  srgbToOklchCss,
  type Srgb,
} from "@/lib/tfl/colour-formats"

/** Go night map paper (charcoal — not pitch black). */
export const GO_NIGHT_PAPER = "#2C2C32"

/**
 * Median day→night OKLCH delta from TfL Go map colour research.
 * Prefer this over raw night hex samples (capture-resistant).
 */
export const GO_NIGHT_OKLCH_DELTA = {
  dL: 0.03325,
  dC: 0.00838,
  dH: 0.776,
} as const

/** TfL Go Northern light fill on dark maps. */
export const NORTHERN_DARK_HEX = "#FCFCFC"

export type Oklch = { L: number; C: number; H: number }

const clamp01 = (n: number) => Math.min(1, Math.max(0, n))

const srgbChannelToLinear = (c: number): number => {
  const s = c / 255
  return s <= 0.04045 ? s / 12.92 : ((s + 0.055) / 1.055) ** 2.4
}

const linearToSrgbChannel = (c: number): number => {
  const s = c <= 0.0031308 ? 12.92 * c : 1.055 * c ** (1 / 2.4) - 0.055
  return Math.round(clamp01(s) * 255)
}

const linearSrgbToOklab = (r: number, g: number, b: number) => {
  const l = 0.4122214708 * r + 0.5363325363 * g + 0.0514459929 * b
  const m = 0.2119034982 * r + 0.6806995451 * g + 0.1073969566 * b
  const s = 0.0883024619 * r + 0.2817188376 * g + 0.6299787005 * b
  const l_ = Math.cbrt(l)
  const m_ = Math.cbrt(m)
  const s_ = Math.cbrt(s)
  return {
    L: 0.2104542553 * l_ + 0.793617785 * m_ - 0.0040720468 * s_,
    a: 1.9779984951 * l_ - 2.428592205 * m_ + 0.4505937099 * s_,
    b: 0.0259040371 * l_ + 0.7827717662 * m_ - 0.808675766 * s_,
  }
}

export const srgbToOklch = (srgb: Srgb): Oklch => {
  const lab = linearSrgbToOklab(
    srgbChannelToLinear(srgb.r),
    srgbChannelToLinear(srgb.g),
    srgbChannelToLinear(srgb.b)
  )
  const C = Math.hypot(lab.a, lab.b)
  let H = (Math.atan2(lab.b, lab.a) * 180) / Math.PI
  if (H < 0) H += 360
  return { L: lab.L, C, H }
}

export const hexToOklch = (hex: string): Oklch => srgbToOklch(parseHex(hex))

export const oklchToSrgb = ({ L, C, H }: Oklch): Srgb => {
  const a = C * Math.cos((H * Math.PI) / 180)
  const b = C * Math.sin((H * Math.PI) / 180)
  const l_ = L + 0.3963377774 * a + 0.2158037573 * b
  const m_ = L - 0.1055613458 * a - 0.0638541728 * b
  const s_ = L - 0.0894841775 * a - 1.291485548 * b
  const l = l_ ** 3
  const mm = m_ ** 3
  const s = s_ ** 3
  return {
    r: linearToSrgbChannel(
      +4.0767416621 * l - 3.3077115913 * mm + 0.2309699292 * s
    ),
    g: linearToSrgbChannel(
      -1.2684380046 * l + 2.6097574011 * mm - 0.3413193965 * s
    ),
    b: linearToSrgbChannel(
      -0.0041960863 * l - 0.7034186147 * mm + 1.707614701 * s
    ),
  }
}

export const oklchToHex = (oklch: Oklch): string => {
  const { r, g, b } = oklchToSrgb(oklch)
  const h = (n: number) => n.toString(16).padStart(2, "0")
  return `#${h(r)}${h(g)}${h(b)}`.toUpperCase()
}

export type NightOklchDelta = {
  dL: number
  dC: number
  dH: number
}

/** Remap a baked GeoJSON line hex for the current basemap. */
export const mapLineColorForBasemap = (hex: string, dark: boolean): string => {
  if (!dark) return hex
  const n = hex.replace("#", "").toUpperCase()
  if (n === "000000" || n === "000") return NORTHERN_DARK_HEX
  return applyBrandNightMethod(hex)
}

/** Apply OKLCH night delta to a brand hex (or any sRGB hex). */
export const applyBrandNightMethod = (
  brandHex: string,
  delta: NightOklchDelta = GO_NIGHT_OKLCH_DELTA
): string => {
  const o = hexToOklch(brandHex)
  let H = o.H + delta.dH
  if (H < 0) H += 360
  if (H >= 360) H -= 360
  return oklchToHex({
    L: Math.min(1, Math.max(0, o.L + delta.dL)),
    C: Math.max(0, o.C + delta.dC),
    H,
  })
}

/** Dark-map OKLCH CSS for a published brand colour (Northern excluded). */
export const darkOklchFromBrandSpec = (spec: BrandColourSpec): string => {
  const nightHex = applyBrandNightMethod(spec.hex)
  return srgbToOklchCss(parseHex(nightHex))
}

export const northernDarkOklch = (): string =>
  srgbToOklchCss(parseHex(NORTHERN_DARK_HEX))

/** Brand RGB → dark OKLCH via night method (for token build). */
export const darkOklchFromRgbChannels = (rgb: string): string => {
  const srgb = parseRgbChannels(rgb)
  const h = (n: number) => n.toString(16).padStart(2, "0")
  const hex = `#${h(srgb.r)}${h(srgb.g)}${h(srgb.b)}`
  return srgbToOklchCss(parseHex(applyBrandNightMethod(hex)))
}

"use client"

import { useCallback, useEffect, useRef } from "react"
import type { FeatureCollection, LineString } from "geojson"
import type maplibregl from "maplibre-gl"
import {
  vehiclesToSegmentGeoJSON,
  type VehiclePosition,
  type VehicleSegmentProperties,
} from "@/lib/tfl/map-vehicles"
import { hopGraphForRailLine } from "@/lib/tfl/vehicle-hop-graph"
import { advanceHopPosition } from "@/lib/tfl/vehicle-hop-engine"
import {
  pathTurnBetween,
  positionBehindStop,
  type RoutePolyline,
} from "@/lib/tfl/vehicle-progress"
import {
  DEFAULT_VEHICLE_VISCOSITY,
  stillDwelling,
  viscosityFactor,
} from "@/lib/tfl/vehicle-viscosity"

const COAST_FRAME_MS = 80
const EASE_MS = 1_200
const SNAP_EPSILON_DEG = 0.00004

const setSegmentData = (
  map: maplibregl.Map,
  sourceId: string,
  collection: FeatureCollection<LineString, VehicleSegmentProperties>
) => {
  const source = map.getSource(sourceId)
  if (source?.type === "geojson") {
    ;(source as maplibregl.GeoJSONSource).setData(collection)
  }
}

const vehicleKey = (vehicle: VehiclePosition): string =>
  `${vehicle.lineId}:${vehicle.vehicleId}`

const easeInOut = (t: number): number =>
  t < 0.5 ? 2 * t * t : 1 - (-2 * t + 2) ** 2 / 2

type EaseState = {
  fromLat: number
  fromLon: number
  fromRemainingKm?: number
  fromStopId?: string
  toStopId?: string
  startMs: number
  durationMs: number
}

const easeDurationMs = (
  from: VehiclePosition,
  to: VehiclePosition,
  polylines: readonly RoutePolyline[]
): number => {
  const turn = pathTurnBetween({
    from: { lat: from.lat, lon: from.lon },
    to: { lat: to.lat, lon: to.lon },
    lineId: to.lineId,
    polylines,
    fromStopId: to.fromStopId ?? from.fromStopId,
    toStopId: to.nextStopId ?? from.nextStopId,
    canonical: hopGraphForRailLine(to.lineId).canonical,
  })
  const remainingKm = Math.min(
    from.remainingKm ?? Number.POSITIVE_INFINITY,
    to.remainingKm ?? Number.POSITIVE_INFINITY
  )
  return (
    EASE_MS *
    viscosityFactor({
      turnRadians: turn,
      remainingKm: Number.isFinite(remainingKm) ? remainingKm : undefined,
      params: DEFAULT_VEHICLE_VISCOSITY,
    })
  )
}

const placeAlongHop = (
  vehicle: VehiclePosition,
  remainingKm: number,
  polylines: readonly RoutePolyline[]
): VehiclePosition => {
  if (vehicle.nextStopLat == null || vehicle.nextStopLon == null) {
    return { ...vehicle, remainingKm }
  }
  const followingStop =
    vehicle.followingStopLat != null && vehicle.followingStopLon != null
      ? { lat: vehicle.followingStopLat, lon: vehicle.followingStopLon }
      : undefined
  const placed = positionBehindStop({
    nextStop: { lat: vehicle.nextStopLat, lon: vehicle.nextStopLon },
    followingStop,
    remainingKm,
    lineId: vehicle.lineId,
    polylines,
    fromStopId: vehicle.fromStopId,
    toStopId: vehicle.nextStopId,
    canonical: hopGraphForRailLine(vehicle.lineId).canonical,
  })
  return {
    ...vehicle,
    lat: placed.lat,
    lon: placed.lon,
    bearingDeg: placed.bearingDeg,
    remainingKm,
  }
}

/**
 * Writes vehicle segments onto an existing GeoJSON source.
 * When `coast` is on, walks each vehicle along its hop using elapsed
 * time and eases onto a new poll's committed target — setData only,
 * never recreates the map.
 */
export const useVehicleSegmentSource = ({
  mapRef,
  sourceId,
  vehicles,
  getPolylines,
  coast = false,
  ready,
}: {
  mapRef: { current: maplibregl.Map | null }
  sourceId: string
  vehicles: readonly VehiclePosition[] | undefined
  getPolylines: () => readonly RoutePolyline[]
  coast?: boolean
  ready: boolean
}) => {
  const vehiclesRef = useRef(vehicles)
  const getPolylinesRef = useRef(getPolylines)
  const renderedRef = useRef<Map<string, VehiclePosition>>(new Map())
  const easesRef = useRef<Map<string, EaseState>>(new Map())
  const lastAsOfRef = useRef<number | null>(null)

  useEffect(() => {
    vehiclesRef.current = vehicles
    getPolylinesRef.current = getPolylines
  })

  const write = useCallback(
    (next: readonly VehiclePosition[]) => {
      const map = mapRef.current
      if (!map) return
      setSegmentData(
        map,
        sourceId,
        vehiclesToSegmentGeoJSON(next, getPolylinesRef.current())
      )
      const nextRendered = new Map<string, VehiclePosition>()
      for (const vehicle of next) {
        nextRendered.set(vehicleKey(vehicle), vehicle)
      }
      renderedRef.current = nextRendered
    },
    [mapRef, sourceId]
  )

  const flush = useCallback(() => {
    write(vehiclesRef.current ?? [])
  }, [write])

  useEffect(() => {
    const map = mapRef.current
    if (!map || !ready) return

    if (!coast) {
      write(vehicles ?? [])
      return
    }

    let frame = 0
    let last = 0
    const tick = (now: number) => {
      if (now - last >= COAST_FRAME_MS) {
        last = now
        const snapshot = vehiclesRef.current ?? []
        const polylines = getPolylinesRef.current()
        const clock = Date.now()
        const snapshotAsOf = snapshot[0]?.asOf ?? null
        if (snapshotAsOf != null && snapshotAsOf !== lastAsOfRef.current) {
          lastAsOfRef.current = snapshotAsOf
          const eases = easesRef.current
          const nextEases = new Map<string, EaseState>()
          for (const vehicle of snapshot) {
            const key = vehicleKey(vehicle)
            const rendered = renderedRef.current.get(key)
            if (
              rendered &&
              (Math.abs(rendered.lat - vehicle.lat) > SNAP_EPSILON_DEG ||
                Math.abs(rendered.lon - vehicle.lon) > SNAP_EPSILON_DEG)
            ) {
              nextEases.set(key, {
                fromLat: rendered.lat,
                fromLon: rendered.lon,
                fromRemainingKm: rendered.remainingKm,
                fromStopId: rendered.fromStopId,
                toStopId: rendered.nextStopId,
                startMs: clock,
                durationMs: easeDurationMs(rendered, vehicle, polylines),
              })
            }
          }
          eases.clear()
          for (const [key, ease] of nextEases) eases.set(key, ease)
        }

        write(
          snapshot.map((vehicle) => {
            const committed = advanceHopPosition(vehicle, clock, polylines)
            const ease = easesRef.current.get(vehicleKey(vehicle))
            if (!ease) return committed
            const t = easeInOut(
              Math.min(1, Math.max(0, (clock - ease.startMs) / ease.durationMs))
            )
            if (t >= 1) {
              easesRef.current.delete(vehicleKey(vehicle))
              return committed
            }
            const hopChanged =
              ease.toStopId != null &&
              committed.nextStopId != null &&
              ease.toStopId !== committed.nextStopId
            if (
              hopChanged &&
              stillDwelling(
                committed.arrivedAtMs ?? ease.startMs,
                clock,
                DEFAULT_VEHICLE_VISCOSITY
              )
            ) {
              return {
                ...committed,
                lat: ease.fromLat,
                lon: ease.fromLon,
                remainingKm: 0,
              }
            }
            const sameHop =
              ease.fromRemainingKm != null &&
              committed.remainingKm != null &&
              !hopChanged &&
              (ease.fromStopId == null ||
                committed.fromStopId == null ||
                ease.fromStopId === committed.fromStopId)
            if (sameHop) {
              const remainingKm =
                ease.fromRemainingKm! +
                (committed.remainingKm! - ease.fromRemainingKm!) * t
              return placeAlongHop(committed, remainingKm, polylines)
            }
            return {
              ...committed,
              lat: ease.fromLat + (committed.lat - ease.fromLat) * t,
              lon: ease.fromLon + (committed.lon - ease.fromLon) * t,
            }
          })
        )
      }
      frame = requestAnimationFrame(tick)
    }
    frame = requestAnimationFrame(tick)
    return () => cancelAnimationFrame(frame)
    // vehicles are read from vehiclesRef so the map is not remounted on polls.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [mapRef, coast, ready, write])

  return { flush }
}

import along from "@turf/along"
import { point } from "@turf/helpers"
import length from "@turf/length"
import { lineSlice } from "@turf/line-slice"
import type { LineString, Position } from "geojson"
import { undirectedHopKey } from "@/lib/tfl/geometry/line-hop-times"

export type StationCoord = {
  lat: number
  lon: number
}

export type RoutePoint = {
  lat: number
  lon: number
  bearingDeg: number
}

const clamp01 = (n: number) => Math.min(1, Math.max(0, n))

const toRad = (deg: number) => (deg * Math.PI) / 180

const bearingDeg = (from: Position, to: Position): number => {
  const φ1 = toRad(from[1] ?? 0)
  const φ2 = toRad(to[1] ?? 0)
  const Δλ = toRad((to[0] ?? 0) - (from[0] ?? 0))
  const y = Math.sin(Δλ) * Math.cos(φ2)
  const x =
    Math.cos(φ1) * Math.sin(φ2) - Math.sin(φ1) * Math.cos(φ2) * Math.cos(Δλ)
  return ((Math.atan2(y, x) * 180) / Math.PI + 360) % 360
}

const squaredDistance = (a: Position, b: Position): number => {
  const dx = (a[0] ?? 0) - (b[0] ?? 0)
  const dy = (a[1] ?? 0) - (b[1] ?? 0)
  return dx * dx + dy * dy
}

const minVertexDistance = (line: LineString, target: Position): number => {
  let best = Number.POSITIVE_INFINITY
  for (const coord of line.coordinates) {
    const d = squaredDistance(coord, target)
    if (d < best) best = d
  }
  return best
}

const angleDiffDeg = (a: number, b: number): number => {
  const raw = Math.abs(a - b) % 360
  return raw > 180 ? 360 - raw : raw
}

const segmentBearingNear = (
  line: LineString,
  target: Position
): number | null => {
  let bestScore = Number.POSITIVE_INFINITY
  let bestBearing: number | null = null
  const coords = line.coordinates
  for (let i = 0; i < coords.length - 1; i++) {
    const a = coords[i]
    const b = coords[i + 1]
    if (!a || !b) continue
    const mid: Position = [
      ((a[0] ?? 0) + (b[0] ?? 0)) / 2,
      ((a[1] ?? 0) + (b[1] ?? 0)) / 2,
    ]
    const score = squaredDistance(target, mid)
    if (score < bestScore) {
      bestScore = score
      bestBearing = bearingDeg(a, b)
    }
  }
  return bestBearing
}

const pickPolyline = (
  polylines: readonly LineString[],
  start: Position,
  end: Position,
  travelBearingDeg?: number
): LineString | null => {
  if (polylines.length === 0) return null
  let best: LineString | null = null
  let bestScore = Number.POSITIVE_INFINITY
  for (const line of polylines) {
    if (line.coordinates.length < 2) continue
    const distance =
      minVertexDistance(line, start) + minVertexDistance(line, end)
    if (travelBearingDeg == null) {
      if (distance < bestScore) {
        best = line
        bestScore = distance
      }
      continue
    }
    const lineBearing = segmentBearingNear(line, start)
    if (lineBearing == null) continue
    const turn = angleDiffDeg(lineBearing, travelBearingDeg)
    if (turn > 60) continue
    const score = distance + 3 * (turn / 180)
    if (score < bestScore) {
      best = line
      bestScore = score
    }
  }
  if (best) return best
  if (travelBearingDeg == null) return null
  return pickPolyline(polylines, start, end)
}

/**
 * 0–1 progress along the segment from the next stop to the stop after,
 * from two `timeToStation` values. Clamped. `0` when the following time
 * is missing or not later than the next time.
 */
export const progressBetweenStops = (
  timeToNextSec: number,
  timeToFollowingSec: number | undefined
): number => {
  if (timeToFollowingSec == null || timeToFollowingSec <= timeToNextSec) {
    return 0
  }
  const segmentTotal = timeToFollowingSec - timeToNextSec
  return clamp01((segmentTotal - timeToNextSec) / segmentTotal)
}

/**
 * A point on route geometry between two stations.
 * `progress` 0 is `from`, 1 is `to`. Snaps to the nearest polyline when given.
 */
export const pointBetweenStations = ({
  from,
  to,
  progress,
  polylines = [],
}: {
  from: StationCoord
  to: StationCoord
  progress: number
  polylines?: readonly LineString[]
}): RoutePoint => {
  const fraction = clamp01(progress)
  const start: Position = [from.lon, from.lat]
  const end: Position = [to.lon, to.lat]
  const line = pickPolyline(polylines, start, end)
  if (line) {
    try {
      const sliced = lineSlice(point(start), point(end), line)
      const km = length(sliced, { units: "kilometers" })
      if (km > 0) {
        const at = along(sliced, km * fraction, { units: "kilometers" })
        const ahead = along(sliced, Math.min(km, km * fraction + km * 0.02), {
          units: "kilometers",
        })
        const coord = at.geometry.coordinates
        return {
          lon: coord[0] ?? from.lon,
          lat: coord[1] ?? from.lat,
          bearingDeg: bearingDeg(coord, ahead.geometry.coordinates),
        }
      }
    } catch {
      // Fall through to a straight lerp.
    }
  }
  return {
    lon: from.lon + (to.lon - from.lon) * fraction,
    lat: from.lat + (to.lat - from.lat) * fraction,
    bearingDeg: bearingDeg(start, end),
  }
}

export type RoutePolyline = {
  lineId?: string
  line: LineString
  /** Canonical station id at one end of a passenger hop. */
  fromStationId?: string
  /** Canonical station id at the other end of a passenger hop. */
  toStationId?: string
  /** Typical timetable minutes for this hop, when known. */
  hopMinutes?: number
}

export const asRoutePolylines = (
  polylines: readonly (LineString | RoutePolyline)[]
): RoutePolyline[] =>
  polylines.map((entry) => ("line" in entry ? entry : { line: entry }))

const identity = (id: string): string => id

/**
 * Prefer the unique-track hop tagged with these two stations.
 * `canonical` maps arrival naptans / hub ids onto the hop's station ids.
 */
export const pickHopPolyline = (
  polylines: readonly (LineString | RoutePolyline)[],
  fromId?: string,
  toId?: string,
  canonical: (id: string) => string = identity
): RoutePolyline | null => {
  if (!fromId || !toId) return null
  const want = undirectedHopKey(canonical(fromId), canonical(toId))
  let best: RoutePolyline | null = null
  for (const row of asRoutePolylines(polylines)) {
    if (!row.fromStationId || !row.toStationId) continue
    const key = undirectedHopKey(
      canonical(row.fromStationId),
      canonical(row.toStationId)
    )
    if (key !== want) continue
    if (!best || row.line.coordinates.length > best.line.coordinates.length) {
      best = row
    }
  }
  return best
}

/**
 * Remaining distance on a locked hop. Prefer timetable minutes when the
 * hop length is known so a 1-minute hop and a 4-minute hop do not share
 * the same assumed speed. Always stays on the hop.
 */
export const remainingKmForHop = ({
  lineId,
  timeToNextSec,
  hopKm,
  hopMinutes,
}: {
  lineId: string
  timeToNextSec: number
  hopKm?: number
  hopMinutes?: number
}): number => {
  const tts = Math.max(0, timeToNextSec)
  if (hopKm != null && hopKm > 0 && hopMinutes != null && hopMinutes > 0) {
    return hopKm * Math.min(1, tts / (hopMinutes * 60))
  }
  const fromSpeed = (vehicleSpeedMetersPerSec(lineId) * tts) / 1000
  return hopKm != null && hopKm > 0 ? Math.min(hopKm, fromSpeed) : fromSpeed
}

const lerpPosition = (a: Position, b: Position, t: number): Position => [
  (a[0] ?? 0) + ((b[0] ?? 0) - (a[0] ?? 0)) * t,
  (a[1] ?? 0) + ((b[1] ?? 0) - (a[1] ?? 0)) * t,
]

const asLineFeature = (line: LineString) => ({
  type: "Feature" as const,
  properties: {},
  geometry: line,
})

const lengthKm = (line: LineString): number =>
  length(asLineFeature(line), { units: "kilometers" })

const segmentLengthKm = (a: Position, b: Position): number =>
  lengthKm({ type: "LineString", coordinates: [a, b] })

const nearestOnLine = (
  line: LineString,
  target: Position
): { distanceKm: number; score: number } => {
  let bestScore = Number.POSITIVE_INFINITY
  let bestDistanceKm = 0
  let travelled = 0
  const coords = line.coordinates
  for (let i = 0; i < coords.length - 1; i++) {
    const a = coords[i]
    const b = coords[i + 1]
    if (!a || !b) continue
    const segKm = segmentLengthKm(a, b)
    const ax = a[0] ?? 0
    const ay = a[1] ?? 0
    const dx = (b[0] ?? 0) - ax
    const dy = (b[1] ?? 0) - ay
    const denom = dx * dx + dy * dy
    const t =
      denom === 0
        ? 0
        : Math.min(
            1,
            Math.max(0, ((target[0] - ax) * dx + (target[1] - ay) * dy) / denom)
          )
    const px = ax + dx * t
    const py = ay + dy * t
    const score = squaredDistance(target, [px, py])
    if (score < bestScore) {
      bestScore = score
      bestDistanceKm = travelled + segKm * t
    }
    travelled += segKm
  }
  return { distanceKm: bestDistanceKm, score: bestScore }
}

/**
 * Assumed average speed including dwell time, used to dead-reckon a
 * vehicle backwards from its next stop. TfL only ever gives a
 * `timeToStation` countdown to a future stop, never a current position or
 * a previous stop, so there is no reliable "progress between two future
 * stops" — the gap between a vehicle's next two predicted stops is
 * usually much shorter than its `timeToStation` to the first of them,
 * which would clamp progress to 0 for most of the journey. Walking
 * backward from the next stop by `speed × timeToStation` instead keeps
 * every vehicle visibly moving for as long as its ETA counts down.
 */
export const vehicleSpeedMetersPerSec = (lineId: string): number => {
  if (lineId === "elizabeth") return 14
  if (lineId === "metropolitan") return 10
  if (lineId === "dlr") return 7
  if (lineId === "tram") return 6
  if (/^\d/.test(lineId) || /^n\d/i.test(lineId)) return 5
  return 8.5
}

/**
 * Walk backward from `nextStop` by a known remaining distance. Used by
 * the hop engine so a locked remaining-km can be re-placed without
 * re-deriving distance from an assumed speed.
 */
export const positionBehindStop = ({
  nextStop,
  followingStop,
  remainingKm,
  lineId,
  polylines,
  fromStopId,
  toStopId,
  canonical,
}: {
  nextStop: StationCoord
  followingStop?: StationCoord
  remainingKm: number
  lineId?: string
  polylines: readonly (LineString | RoutePolyline)[]
  fromStopId?: string
  toStopId?: string
  canonical?: (id: string) => string
}): RoutePoint => {
  const nextPos: Position = [nextStop.lon, nextStop.lat]
  const followingPos: Position | undefined = followingStop
    ? [followingStop.lon, followingStop.lat]
    : undefined
  const travelBearingDeg = followingPos
    ? bearingDeg(nextPos, followingPos)
    : undefined

  const rows = asRoutePolylines(polylines).filter(
    (row) => row.line.coordinates.length >= 2
  )
  const preferred = lineId ? rows.filter((row) => row.lineId === lineId) : rows
  const pool = preferred.length > 0 ? preferred : rows
  const hop = pickHopPolyline(pool, fromStopId, toStopId, canonical)
  const line =
    hop?.line ??
    pickPolyline(
      pool.map((row) => row.line),
      nextPos,
      followingPos ?? nextPos,
      travelBearingDeg
    )

  if (!line) {
    return { lat: nextStop.lat, lon: nextStop.lon, bearingDeg: 0 }
  }

  const totalKm = lengthKm(line)
  const dNext = nearestOnLine(line, nextPos).distanceKm
  const distanceBackKm = Math.min(Math.max(0, remainingKm), totalKm)
  let targetKm: number
  if (hop && hop.line.coordinates.length >= 2) {
    const start = hop.line.coordinates[0]!
    const end = hop.line.coordinates[hop.line.coordinates.length - 1]!
    const fromIsStart =
      squaredDistance(start, nextPos) > squaredDistance(end, nextPos)
    targetKm = fromIsStart
      ? Math.max(0, dNext - distanceBackKm)
      : Math.min(totalKm, dNext + distanceBackKm)
  } else {
    const goingForward = followingPos
      ? nearestOnLine(line, followingPos).distanceKm >= dNext
      : true
    targetKm = goingForward
      ? Math.max(0, dNext - distanceBackKm)
      : Math.min(totalKm, dNext + distanceBackKm)
  }

  const at = along(asLineFeature(line), targetKm, { units: "kilometers" })
  const coord = at.geometry.coordinates
  return {
    lon: coord[0] ?? nextStop.lon,
    lat: coord[1] ?? nextStop.lat,
    bearingDeg: bearingDeg(coord, nextPos),
  }
}

/** Polyline length between two stations, or 0 when they cannot be sliced. */
export const hopLengthKm = ({
  from,
  to,
  lineId,
  polylines,
  fromStopId,
  toStopId,
  canonical,
}: {
  from: StationCoord
  to: StationCoord
  lineId?: string
  polylines: readonly (LineString | RoutePolyline)[]
  fromStopId?: string
  toStopId?: string
  canonical?: (id: string) => string
}): number => {
  const rows = asRoutePolylines(polylines).filter(
    (row) => row.line.coordinates.length >= 2
  )
  const preferred = lineId ? rows.filter((row) => row.lineId === lineId) : rows
  const pool = preferred.length > 0 ? preferred : rows
  const hop = pickHopPolyline(pool, fromStopId, toStopId, canonical)
  if (hop) {
    const km = lengthKm(hop.line)
    return Number.isFinite(km) ? km : 0
  }
  const start: Position = [from.lon, from.lat]
  const end: Position = [to.lon, to.lat]
  const line = pickPolyline(
    pool.map((row) => row.line),
    start,
    end,
    bearingDeg(start, end)
  )
  if (!line) return 0
  try {
    const sliced = lineSlice(point(start), point(end), line)
    const km = length(sliced, { units: "kilometers" })
    return Number.isFinite(km) ? km : 0
  } catch {
    return 0
  }
}

/**
 * Dead-reckons a vehicle's position by walking backward from `nextStop`
 * along the nearest polyline, by `speedMetersPerSec × timeToNextSec`.
 * `followingStop`, when known, only picks which of the two directions
 * along the polyline is "backward" (away from where the vehicle is
 * headed next) — it is not used as an interpolation endpoint. Converges
 * exactly on `nextStop` as `timeToNextSec` reaches 0.
 */
export const positionApproachingStop = ({
  nextStop,
  followingStop,
  timeToNextSec,
  speedMetersPerSec,
  lineId,
  polylines,
  fromStopId,
  toStopId,
  canonical,
}: {
  nextStop: StationCoord
  followingStop?: StationCoord
  timeToNextSec: number
  speedMetersPerSec: number
  lineId?: string
  polylines: readonly (LineString | RoutePolyline)[]
  fromStopId?: string
  toStopId?: string
  canonical?: (id: string) => string
}): RoutePoint =>
  positionBehindStop({
    nextStop,
    followingStop,
    remainingKm: (speedMetersPerSec * Math.max(0, timeToNextSec)) / 1000,
    lineId,
    polylines,
    fromStopId,
    toStopId,
    canonical,
  })

const sliceLineByKm = (
  line: LineString,
  startKm: number,
  endKm: number
): Position[] => {
  const start = Math.min(startKm, endKm)
  const end = Math.max(startKm, endKm)
  const out: Position[] = []
  let travelled = 0
  const coords = line.coordinates
  for (let i = 0; i < coords.length - 1; i++) {
    const a = coords[i]
    const b = coords[i + 1]
    if (!a || !b) continue
    const segKm = segmentLengthKm(a, b)
    const segStart = travelled
    const segEnd = travelled + segKm
    travelled = segEnd
    if (segEnd < start || segStart > end) continue
    if (out.length === 0) {
      const t = segKm === 0 ? 0 : (start - segStart) / segKm
      out.push(lerpPosition(a, b, Math.min(1, Math.max(0, t))))
    }
    if (segStart > start && segStart < end) out.push(a)
    if (segStart <= end && end <= segEnd) {
      const t = segKm === 0 ? 1 : (end - segStart) / segKm
      out.push(lerpPosition(a, b, Math.min(1, Math.max(0, t))))
    }
  }
  return out
}

/**
 * In-service length along the track. Elizabeth is a 9-car Class 345;
 * most Tube stock is shorter. Trams are a single short unit. Bus routes
 * are the vehicle, not a train.
 */
export const vehicleLengthMeters = (lineId: string): number => {
  if (lineId === "elizabeth") return 205
  if (lineId === "metropolitan") return 160
  if (lineId === "dlr") return 56
  if (lineId === "tram") return 20
  if (/^\d/.test(lineId) || /^n\d/i.test(lineId)) return 12
  return 133
}

/** Stroke scale so short stock is not as fat as a Tube train. */
export const vehicleStrokeScale = (lineId: string): number => {
  if (lineId === "tram") return 0.52
  if (lineId === "dlr") return 0.72
  if (/^\d/.test(lineId) || /^n\d/i.test(lineId)) return 0.55
  return 1
}

/** Order a slice so it points the same way the vehicle is travelling. */
export const orientLineToBearing = (
  line: LineString,
  travelBearingDeg: number
): LineString => {
  const coords = line.coordinates
  if (coords.length < 2) return line
  const start = coords[0]
  const end = coords[coords.length - 1]
  if (!start || !end) return line
  if (angleDiffDeg(bearingDeg(start, end), travelBearingDeg) <= 90) return line
  return { type: "LineString", coordinates: [...coords].reverse() }
}

/** Total turning, in radians, along a polyline. */
export const pathTurnRadians = (coordinates: readonly Position[]): number => {
  let turn = 0
  let previous: number | null = null
  for (let index = 0; index < coordinates.length - 1; index += 1) {
    const from = coordinates[index]
    const to = coordinates[index + 1]
    if (!from || !to) continue
    const heading = bearingDeg(from, to)
    if (previous != null) turn += toRad(angleDiffDeg(previous, heading))
    previous = heading
  }
  return turn
}

/**
 * Stretch an ease when the path between two points bends.
 * 0 turn → 1; a half-turn → about 1.5; capped at 2.6.
 */
export const curvatureEaseFactor = (turnRadians: number): number =>
  1 + Math.min(1.6, Math.max(0, turnRadians) / Math.PI)

export const pathTurnBetween = ({
  from,
  to,
  lineId,
  polylines,
  fromStopId,
  toStopId,
  canonical,
}: {
  from: StationCoord
  to: StationCoord
  lineId?: string
  polylines: readonly (LineString | RoutePolyline)[]
  fromStopId?: string
  toStopId?: string
  canonical?: (id: string) => string
}): number => {
  const start: Position = [from.lon, from.lat]
  const end: Position = [to.lon, to.lat]
  const rows = asRoutePolylines(polylines).filter(
    (row) => row.line.coordinates.length >= 2
  )
  const preferred = lineId ? rows.filter((row) => row.lineId === lineId) : rows
  const pool = preferred.length > 0 ? preferred : rows
  const hop = pickHopPolyline(pool, fromStopId, toStopId, canonical)
  const line =
    hop?.line ??
    pickPolyline(
      pool.map((row) => row.line),
      start,
      end
    )
  if (!line) return 0
  const a = nearestOnLine(line, start).distanceKm
  const b = nearestOnLine(line, end).distanceKm
  const coordinates = sliceLineByKm(line, Math.min(a, b), Math.max(a, b))
  return pathTurnRadians(
    coordinates.length >= 2 ? coordinates : line.coordinates
  )
}

/**
 * A track-following segment centred on `at`, true to `lengthMeters`.
 * Uses the nearest OSM polyline so the body follows that branch's curve.
 */
export const segmentAroundPoint = ({
  at,
  lengthMeters,
  lineId,
  polylines,
  fromStopId,
  toStopId,
  canonical,
}: {
  at: StationCoord
  lengthMeters: number
  lineId?: string
  polylines: readonly (LineString | RoutePolyline)[]
  fromStopId?: string
  toStopId?: string
  canonical?: (id: string) => string
}): LineString => {
  const target: Position = [at.lon, at.lat]
  const rows = asRoutePolylines(polylines).filter(
    (row) => row.line.coordinates.length >= 2
  )
  const preferred = lineId ? rows.filter((row) => row.lineId === lineId) : rows
  const pool = preferred.length > 0 ? preferred : rows
  const hop = pickHopPolyline(pool, fromStopId, toStopId, canonical)
  const halfKm = Math.max(lengthMeters, 8) / 2000
  let best: RoutePolyline | null = null
  let bestHit = { distanceKm: 0, score: Number.POSITIVE_INFINITY }
  let bestSpan = -1
  const hopHit = hop ? nearestOnLine(hop.line, target) : null
  const nearScore = hopHit ? hopHit.score * 8 + 1e-14 : Number.POSITIVE_INFINITY
  for (const row of pool) {
    const hit = nearestOnLine(row.line, target)
    if (hopHit && hit.score > nearScore && hit.score > hopHit.score) continue
    const total = lengthKm(row.line)
    const span =
      Math.min(hit.distanceKm, halfKm) +
      Math.min(Math.max(0, total - hit.distanceKm), halfKm)
    const closer = hit.score < bestHit.score * 0.5
    const roomier = span > bestSpan + 1e-6 && hit.score <= bestHit.score * 8
    if (!best || closer || (roomier && hit.score <= nearScore)) {
      best = row
      bestHit = hit
      bestSpan = span
    }
  }
  if (!best && hop) {
    best = hop
    bestHit = hopHit ?? nearestOnLine(hop.line, target)
  }
  if (!best) {
    return {
      type: "LineString",
      coordinates: [
        [at.lon - 0.0002, at.lat],
        [at.lon + 0.0002, at.lat],
      ],
    }
  }
  const totalKm = lengthKm(best.line)
  const startKm = Math.max(0, bestHit.distanceKm - halfKm)
  const endKm = Math.min(totalKm, bestHit.distanceKm + halfKm)
  const coordinates = sliceLineByKm(best.line, startKm, endKm)
  if (coordinates.length >= 2) {
    return { type: "LineString", coordinates }
  }
  const fallback = along(asLineFeature(best.line), bestHit.distanceKm, {
    units: "kilometers",
  }).geometry.coordinates
  return {
    type: "LineString",
    coordinates: [
      fallback,
      [(fallback[0] ?? at.lon) + 0.00015, fallback[1] ?? at.lat],
    ],
  }
}

import { STATION_HUBS } from "tfl-ts"
import {
  buildLineTopologyFromStaticBranches,
  type LineTopology,
} from "@/lib/tfl/line-topology"

export type HopNeighbor = {
  stationId: string
  branchId: string
}

export type HopGraph = {
  /** Canonical station id → adjacent canonical ids. Undirected. */
  adjacent: ReadonlyMap<string, ReadonlySet<string>>
  incoming: ReadonlyMap<string, readonly HopNeighbor[]>
  canonical: (id: string) => string
  branched: boolean
}

const EMPTY_GRAPH: HopGraph = {
  adjacent: new Map(),
  incoming: new Map(),
  canonical: (id) => id,
  branched: false,
}

const buildAliasCanonical = (
  groups: readonly (readonly string[])[]
): Map<string, string> => {
  const map = new Map<string, string>()
  for (const group of groups) {
    const ids = [...new Set(group.map((id) => id.trim()).filter(Boolean))]
    if (ids.length === 0) continue
    const root = ids[0]!
    for (const id of ids) map.set(id, root)
  }
  return map
}

/** Naptan / hub / line-member ids that refer to the same station. */
export const stationHubAliasGroups = (): string[][] => {
  const groups: string[][] = []
  for (const [id, hub] of Object.entries(STATION_HUBS)) {
    const ids = [
      id,
      hub.hubId,
      ...hub.members.map((member) => member.id),
      ...Object.values(hub.lineMemberIds),
    ].filter((value): value is string => Boolean(value))
    if (ids.length > 1) groups.push(ids)
  }
  return groups
}

const graphFromEdges = (
  edges: readonly {
    fromStationId: string
    toStationId: string
    branchId: string
  }[],
  aliasGroups: readonly (readonly string[])[] = []
): HopGraph => {
  const aliases = buildAliasCanonical(aliasGroups)
  const canonical = (id: string): string => aliases.get(id) ?? id

  const adjacent = new Map<string, Set<string>>()
  const incoming = new Map<string, HopNeighbor[]>()
  const addAdj = (a: string, b: string) => {
    const set = adjacent.get(a) ?? new Set<string>()
    set.add(b)
    adjacent.set(a, set)
  }

  for (const edge of edges) {
    const from = canonical(edge.fromStationId)
    const to = canonical(edge.toStationId)
    if (!from || !to || from === to) continue
    addAdj(from, to)
    addAdj(to, from)
    const list = incoming.get(to) ?? []
    list.push({ stationId: from, branchId: edge.branchId })
    incoming.set(to, list)
  }

  let branched = false
  for (const neighbors of adjacent.values()) {
    if (neighbors.size > 2) {
      branched = true
      break
    }
  }

  return {
    adjacent,
    incoming,
    canonical,
    branched,
  }
}

export const hopGraphFromTopology = (
  topology: LineTopology | null,
  aliasGroups: readonly (readonly string[])[] = []
): HopGraph => {
  if (!topology || topology.edges.length === 0) return EMPTY_GRAPH
  return graphFromEdges(topology.edges, aliasGroups)
}

export const hopGraphFromOrderedStops = (
  stationIds: readonly string[],
  aliasGroups: readonly (readonly string[])[] = []
): HopGraph => {
  const edges = []
  for (let i = 0; i < stationIds.length - 1; i++) {
    const from = stationIds[i]
    const to = stationIds[i + 1]
    if (!from || !to) continue
    edges.push({ fromStationId: from, toStationId: to, branchId: "spine" })
  }
  return graphFromEdges(edges, aliasGroups)
}

const railHopGraphCache = new Map<string, HopGraph>()

/** Rail hop graph from static `LINE_STATION_SEQUENCES`, with hub aliases. */
export const hopGraphForRailLine = (lineId: string): HopGraph => {
  const cached = railHopGraphCache.get(lineId)
  if (cached) return cached
  const graph = hopGraphFromTopology(
    buildLineTopologyFromStaticBranches(lineId),
    stationHubAliasGroups()
  )
  railHopGraphCache.set(lineId, graph)
  return graph
}

export const areAdjacent = (
  graph: HopGraph,
  fromId: string,
  toId: string
): boolean => {
  const from = graph.canonical(fromId)
  const to = graph.canonical(toId)
  if (from === to) return true
  return graph.adjacent.get(from)?.has(to) ?? false
}

export const uniqueIncoming = (
  graph: HopGraph,
  toId: string
): HopNeighbor | undefined => {
  const incoming = graph.incoming.get(graph.canonical(toId)) ?? []
  if (incoming.length === 1) return incoming[0]
  return undefined
}

export const hopGraphHasEdges = (graph: HopGraph): boolean =>
  graph.adjacent.size > 0

/**
 * Format helpers for TfL brand colours.
 *
 * Published Pantone / CMYK / NCS stay as authored in `brand-colours`.
 * Screen extras (OKLCH, Display P3) are derived by treating the published RGB
 * as **sRGB** (Colour standard §1 — RGB for displays), then converting with
 * Björn Ottosson’s OKLab and the CSS Color 4 sRGB↔Display-P3 matrices.
 * Dark-map OKLCH/hex use the Go night method in `dark-line-colours`.
 */

import type { BrandColourSpec } from "@/lib/tfl/brand-colours"
import {
  applyBrandNightMethod,
  NORTHERN_DARK_HEX,
} from "@/lib/tfl/dark-line-colours"

export type Srgb = { r: number; g: number; b: number }

export type ColourFormatRow = {
  label: string
  value: string
}

const clamp01 = (n: number) => Math.min(1, Math.max(0, n))

export const parseRgbChannels = (rgb: string): Srgb => {
  const [r, g, b] = rgb.split(/\s+/).map(Number)
  return { r, g, b }
}

export const parseHex = (hex: string): Srgb => {
  const h = hex.replace("#", "")
  return {
    r: Number.parseInt(h.slice(0, 2), 16),
    g: Number.parseInt(h.slice(2, 4), 16),
    b: Number.parseInt(h.slice(4, 6), 16),
  }
}

const srgbChannelToLinear = (c: number): number => {
  const s = c / 255
  return s <= 0.04045 ? s / 12.92 : ((s + 0.055) / 1.055) ** 2.4
}

const linearToSrgbChannel = (c: number): number => {
  const s = c <= 0.0031308 ? 12.92 * c : 1.055 * c ** (1 / 2.4) - 0.055
  return Math.round(clamp01(s) * 255)
}

/** Linear sRGB → OKLab (Ottosson). */
const linearSrgbToOklab = (r: number, g: number, b: number) => {
  const l = 0.4122214708 * r + 0.5363325363 * g + 0.0514459929 * b
  const m = 0.2119034982 * r + 0.6806995451 * g + 0.1073969566 * b
  const s = 0.0883024619 * r + 0.2817188376 * g + 0.6299787005 * b
  const l_ = Math.cbrt(l)
  const m_ = Math.cbrt(m)
  const s_ = Math.cbrt(s)
  return {
    L: 0.2104542553 * l_ + 0.793617785 * m_ - 0.0040720468 * s_,
    a: 1.9779984951 * l_ - 2.428592205 * m_ + 0.4505937099 * s_,
    b: 0.0259040371 * l_ + 0.7827717662 * m_ - 0.808675766 * s_,
  }
}

/** OKLab → OKLCH. */
const oklabToOklch = ({ L, a, b }: { L: number; a: number; b: number }) => {
  const C = Math.hypot(a, b)
  let H = (Math.atan2(b, a) * 180) / Math.PI
  if (H < 0) H += 360
  return { L, C, H }
}

/** Linear sRGB → CIE XYZ (D65). */
const linearSrgbToXyz = (r: number, g: number, b: number) => ({
  x: 0.4123907993 * r + 0.3575843394 * g + 0.1804807884 * b,
  y: 0.2126390059 * r + 0.7151686788 * g + 0.0721923154 * b,
  z: 0.0193308187 * r + 0.1191947798 * g + 0.9505321522 * b,
})

/** CIE XYZ (D65) → linear Display P3. */
const xyzToLinearP3 = (x: number, y: number, z: number) => ({
  r: 2.4934969119 * x - 0.9313836179 * y - 0.4027107845 * z,
  g: -0.8294868756 * x + 1.7626998057 * y + 0.0236256856 * z,
  b: 0.0358458302 * x - 0.0761723893 * y + 0.956884524 * z,
})

const linearToP3Channel = (c: number): number => {
  const v = clamp01(c)
  return v <= 0.0031308 ? 12.92 * v : 1.055 * v ** (1 / 2.4) - 0.055
}

const fmt = (n: number, digits: number) => {
  const s = n.toFixed(digits)
  return s.replace(/\.?0+$/, "") || "0"
}

/** Absolute OKLCH CSS from sRGB 0–255 (TfL published RGB as sRGB). */
export const srgbToOklchCss = (srgb: Srgb): string => {
  const r = srgbChannelToLinear(srgb.r)
  const g = srgbChannelToLinear(srgb.g)
  const b = srgbChannelToLinear(srgb.b)
  const { L, C, H } = oklabToOklch(linearSrgbToOklab(r, g, b))
  if (C < 0.0001) return `oklch(${fmt(L * 100, 3)}% 0 0)`
  return `oklch(${fmt(L * 100, 3)}% ${fmt(C, 4)} ${fmt(H, 2)})`
}

/**
 * Display-P3 CSS `color()` encoding of the same stimulus as sRGB.
 * Same chromaticity — not a boosted “vivid” remapping.
 */
export const srgbToDisplayP3Css = (srgb: Srgb): string => {
  const lr = srgbChannelToLinear(srgb.r)
  const lg = srgbChannelToLinear(srgb.g)
  const lb = srgbChannelToLinear(srgb.b)
  const xyz = linearSrgbToXyz(lr, lg, lb)
  const p3 = xyzToLinearP3(xyz.x, xyz.y, xyz.z)
  return `color(display-p3 ${fmt(linearToP3Channel(p3.r), 4)} ${fmt(linearToP3Channel(p3.g), 4)} ${fmt(linearToP3Channel(p3.b), 4)})`
}

export const formatRgbCss = (srgb: Srgb): string =>
  `rgb(${srgb.r} ${srgb.g} ${srgb.b})`

export const formatHex = (srgb: Srgb): string => {
  const h = (n: number) => n.toString(16).padStart(2, "0")
  return `#${h(srgb.r)}${h(srgb.g)}${h(srgb.b)}`.toUpperCase()
}

/** Round-trip check helper (tests / tooling). */
export const oklchCssToSrgbApprox = (oklch: string): Srgb | null => {
  const m = oklch.match(/oklch\(\s*([\d.]+)%\s+([\d.]+)\s+([\d.]+)\s*\)/i)
  if (!m) return null
  const L = Number(m[1]) / 100
  const C = Number(m[2])
  const H = (Number(m[3]) * Math.PI) / 180
  const a = C * Math.cos(H)
  const b = C * Math.sin(H)
  const l_ = L + 0.3963377774 * a + 0.2158037573 * b
  const m_ = L - 0.1055613458 * a - 0.0638541728 * b
  const s_ = L - 0.0894841775 * a - 1.291485548 * b
  const l = l_ ** 3
  const mm = m_ ** 3
  const s = s_ ** 3
  const r = +4.0767416621 * l - 3.3077115913 * mm + 0.2309699292 * s
  const g = -1.2684380046 * l + 2.6097574011 * mm - 0.3413193965 * s
  const bl = -0.0041960863 * l - 0.7034186147 * mm + 1.707614701 * s
  return {
    r: linearToSrgbChannel(r),
    g: linearToSrgbChannel(g),
    b: linearToSrgbChannel(bl),
  }
}

/**
 * Copyable format rows for a published brand colour.
 * Order: light OKLCH/hex → dark OKLCH/hex → print tokens from the PDF.
 */
export const brandColourFormats = (
  spec: BrandColourSpec,
  opts?: { lineId?: string }
): ColourFormatRow[] => {
  const row = brandColourTableRow(spec, opts)
  return [
    ...row.screen.map((col) => ({ label: col.label, value: col.value })),
    { label: "CMYK", value: spec.cmyk },
    { label: "Pantone", value: spec.pantone },
    {
      label: "NCS",
      value: spec.ncs === "N/A" ? "none available" : spec.ncs,
    },
  ]
}

/** Parse Colour-standard CMYK (`C6 M98 Y100 K1`) → 0–1 channels. */
export const parseCmyk = (
  cmyk: string
): { c: number; m: number; y: number; k: number } | null => {
  const m = cmyk.match(
    /C\s*([\d.]+)\s*M\s*([\d.]+)\s*Y\s*([\d.]+)\s*K\s*([\d.]+)/i
  )
  if (!m) return null
  return {
    c: Number(m[1]) / 100,
    m: Number(m[2]) / 100,
    y: Number(m[3]) / 100,
    k: Number(m[4]) / 100,
  }
}

/**
 * CSS Color 4 `device-cmyk()` for screen emulation of the published print build.
 * Unsupported browsers ignore it; UI always supplies an sRGB fallback.
 */
export const cmykToDeviceCmykCss = (cmyk: string): string | null => {
  const ch = parseCmyk(cmyk)
  if (!ch) return null
  const f = (n: number) => fmt(n, 4)
  return `device-cmyk(${f(ch.c)} ${f(ch.m)} ${f(ch.y)} ${f(ch.k)})`
}

export type ColourTableScreenCol = {
  key: "oklch-light" | "hex-light" | "oklch-dark" | "hex-dark"
  label: string
  /** Exact CSS color for the cell’s underside swatch. */
  cssColor: string
  /** Copied / shown value. */
  value: string
  /** Dark columns sit on charcoal paper so light fills stay visible. */
  nightPaper?: boolean
}

export type ColourTablePrintCell = {
  /** Joined printable tokens for copy. */
  value: string
  lines: string[]
  /** `device-cmyk(...)` when CMYK is published; else sRGB hex. */
  cssColor: string
  /** sRGB fallback when device-cmyk is unsupported. */
  cssFallback: string
}

export type ColourTableRow = {
  hex: string
  darkHex: string
  screen: ColourTableScreenCol[]
  print: ColourTablePrintCell
}

/** Column model for the formats table (light + dark OKLCH/hex, then print). */
export const brandColourTableRow = (
  spec: BrandColourSpec,
  opts?: { lineId?: string }
): ColourTableRow => {
  const srgb = parseRgbChannels(spec.rgb)
  const hex = spec.hex.startsWith("#") ? spec.hex : formatHex(srgb)
  const oklch = srgbToOklchCss(srgb)
  const darkHex =
    opts?.lineId === "northern" ? NORTHERN_DARK_HEX : applyBrandNightMethod(hex)
  const darkOklch = srgbToOklchCss(parseHex(darkHex))
  const deviceCmyk = cmykToDeviceCmykCss(spec.cmyk)
  const printLines = [
    spec.cmyk !== "N/A" ? spec.cmyk : "CMYK N/A",
    spec.pantone !== "N/A" ? spec.pantone : "Pantone N/A",
    spec.ncs !== "N/A" ? spec.ncs : "NCS none available",
  ]

  return {
    hex,
    darkHex,
    screen: [
      { key: "oklch-light", label: "OKLCH", cssColor: oklch, value: oklch },
      { key: "hex-light", label: "HEX", cssColor: hex, value: hex },
      {
        key: "oklch-dark",
        label: "OKLCH dark",
        cssColor: darkOklch,
        value: darkOklch,
        nightPaper: true,
      },
      {
        key: "hex-dark",
        label: "HEX dark",
        cssColor: darkHex,
        value: darkHex,
        nightPaper: true,
      },
    ],
    print: {
      value: printLines.join(" · "),
      lines: printLines,
      cssColor: deviceCmyk ?? hex,
      cssFallback: hex,
    },
  }
}

import type { LineString } from "geojson"
import type { RealtimePrediction } from "tfl-ts"
import type { VehiclePosition } from "@/lib/tfl/map-vehicles"
import {
  areAdjacent,
  hopGraphForRailLine,
  hopGraphHasEdges,
  uniqueIncoming,
  type HopGraph,
} from "@/lib/tfl/vehicle-hop-graph"
import {
  hopLengthKm,
  pathTurnBetween,
  pickHopPolyline,
  positionBehindStop,
  remainingKmForHop,
  vehicleSpeedMetersPerSec,
  type RoutePolyline,
  type StationCoord,
} from "@/lib/tfl/vehicle-progress"
import {
  DEFAULT_VEHICLE_VISCOSITY,
  stillDwelling,
  viscousDrainKm,
  type VehicleViscosityParams,
} from "@/lib/tfl/vehicle-viscosity"

export type VehicleAlgorithm =
  "branch-aware" | "simple-hop-lock" | "gps" | "dead-reckoning"

export type VehicleHopTrack = {
  lineId: string
  vehicleId: string
  toStationId: string
  fromStationId?: string
  branchId?: string
  remainingKm: number
  hopDurationSecEstimate: number
  lastSeenAsOf: number
  dueSinceMs?: number
  destinationName: string
  nextStopLat: number
  nextStopLon: number
  followingStopLat?: number
  followingStopLon?: number
  /** Epoch ms when remaining km first hit 0 on this hop. */
  arrivedAtMs?: number
}

export const vehicleTrackKey = (lineId: string, vehicleId: string): string =>
  `${lineId}:${vehicleId}`

export const algorithmForGraph = (
  graph: HopGraph | null,
  busSource: "gps" | "dead-reckoning" = "dead-reckoning"
): VehicleAlgorithm => {
  if (busSource === "gps") return "gps"
  if (!graph || !hopGraphHasEdges(graph)) return "dead-reckoning"
  return graph.branched ? "branch-aware" : "simple-hop-lock"
}

const DUE_TTS_SEC = 2
const STALE_DUE_MS = 50_000

type GroupedPrediction = {
  vehicleId: string
  lineId: string
  rows: RealtimePrediction[]
}

const groupPredictions = (
  predictions: readonly RealtimePrediction[]
): GroupedPrediction[] => {
  const groups = new Map<string, GroupedPrediction>()
  for (const prediction of predictions) {
    const vehicleId = prediction.vehicleId?.trim()
    if (!vehicleId) continue
    const lineId = prediction.lineId?.trim() ?? ""
    const key = vehicleTrackKey(lineId, vehicleId)
    const existing = groups.get(key)
    if (existing) existing.rows.push(prediction)
    else groups.set(key, { vehicleId, lineId, rows: [prediction] })
  }
  const out: GroupedPrediction[] = []
  for (const group of groups.values()) {
    group.rows.sort(
      (a, b) => (a.timeToStation ?? 9e9) - (b.timeToStation ?? 9e9)
    )
    out.push(group)
  }
  return out
}

const remainingFromEta = (
  lineId: string,
  timeToNextSec: number,
  hopKm?: number,
  hopMinutes?: number
): number =>
  remainingKmForHop({
    lineId,
    timeToNextSec,
    hopKm,
    hopMinutes,
  })

const hopLookup = (
  polylines: readonly (LineString | RoutePolyline)[],
  fromId: string | undefined,
  toId: string,
  graph: HopGraph | null
) => pickHopPolyline(polylines, fromId, toId, graph?.canonical)

const hopKmBetween = ({
  from,
  to,
  fromId,
  toId,
  lineId,
  polylines,
  graph,
}: {
  from?: StationCoord
  to: StationCoord
  fromId?: string
  toId: string
  lineId: string
  polylines: readonly (LineString | RoutePolyline)[]
  graph: HopGraph | null
}): { hopKm?: number; hopMinutes?: number } => {
  const hop = hopLookup(polylines, fromId, toId, graph)
  if (hop) {
    const hopKm = hopLengthKm({
      from: from ?? to,
      to,
      lineId,
      polylines: [hop],
      fromStopId: fromId,
      toStopId: toId,
      canonical: graph?.canonical,
    })
    return {
      hopKm: hopKm > 0 ? hopKm : undefined,
      hopMinutes: hop.hopMinutes,
    }
  }
  if (!from) return {}
  const hopKm = hopLengthKm({
    from,
    to,
    lineId,
    polylines,
    fromStopId: fromId,
    toStopId: toId,
    canonical: graph?.canonical,
  })
  return { hopKm: hopKm > 0 ? hopKm : undefined }
}

const coastRemaining = (
  track: VehicleHopTrack,
  nowMs: number,
  lineId: string,
  viscosity?: VehicleViscosityParams
): number => {
  const elapsedSec = Math.max(0, (nowMs - track.lastSeenAsOf) / 1000)
  return viscousDrainKm({
    remainingKm: track.remainingKm,
    elapsedSec,
    speedMetersPerSec: vehicleSpeedMetersPerSec(lineId),
    params: viscosity,
  }).remainingKm
}

const markArrival = (track: VehicleHopTrack, asOf: number): VehicleHopTrack =>
  track.remainingKm <= 0
    ? { ...track, remainingKm: 0, arrivedAtMs: track.arrivedAtMs ?? asOf }
    : { ...track, arrivedAtMs: undefined }

const toPosition = (
  track: VehicleHopTrack,
  placed: { lat: number; lon: number; bearingDeg: number },
  timeToNextStationSec: number,
  asOf: number
): VehiclePosition => ({
  vehicleId: track.vehicleId,
  lineId: track.lineId,
  lat: placed.lat,
  lon: placed.lon,
  bearingDeg: placed.bearingDeg,
  destinationName: track.destinationName,
  timeToNextStationSec,
  asOf,
  nextStopLat: track.nextStopLat,
  nextStopLon: track.nextStopLon,
  followingStopLat: track.followingStopLat,
  followingStopLon: track.followingStopLon,
  nextStopId: track.toStationId,
  fromStopId: track.fromStationId,
  remainingKm: track.remainingKm,
  arrivedAtMs: track.arrivedAtMs,
})

const placeTrack = (
  track: VehicleHopTrack,
  polylines: readonly (LineString | RoutePolyline)[],
  graph: HopGraph | null
): { lat: number; lon: number; bearingDeg: number } =>
  positionBehindStop({
    nextStop: { lat: track.nextStopLat, lon: track.nextStopLon },
    followingStop:
      track.followingStopLat != null && track.followingStopLon != null
        ? { lat: track.followingStopLat, lon: track.followingStopLon }
        : undefined,
    remainingKm: track.remainingKm,
    lineId: track.lineId,
    polylines,
    fromStopId: track.fromStationId,
    toStopId: track.toStationId,
    canonical: graph?.canonical,
  })

const seedTrack = ({
  lineId,
  vehicleId,
  toStationId,
  nextStop,
  followingStop,
  timeToNextSec,
  destinationName,
  asOf,
  graph,
  polylines,
}: {
  lineId: string
  vehicleId: string
  toStationId: string
  nextStop: StationCoord
  followingStop?: StationCoord
  timeToNextSec: number
  destinationName: string
  asOf: number
  graph: HopGraph | null
  polylines: readonly (LineString | RoutePolyline)[]
}): VehicleHopTrack => {
  const inferred = graph ? uniqueIncoming(graph, toStationId) : undefined
  const hop = hopKmBetween({
    to: nextStop,
    fromId: inferred?.stationId,
    toId: toStationId,
    lineId,
    polylines,
    graph,
  })
  return {
    lineId,
    vehicleId,
    toStationId,
    fromStationId: inferred?.stationId,
    branchId: inferred?.branchId,
    remainingKm: remainingFromEta(
      lineId,
      timeToNextSec,
      hop.hopKm,
      hop.hopMinutes
    ),
    hopDurationSecEstimate: Math.max(timeToNextSec, 1),
    lastSeenAsOf: asOf,
    dueSinceMs: timeToNextSec <= DUE_TTS_SEC ? asOf : undefined,
    destinationName,
    nextStopLat: nextStop.lat,
    nextStopLon: nextStop.lon,
    followingStopLat: followingStop?.lat,
    followingStopLon: followingStop?.lon,
  }
}

/**
 * Ingest a fresh arrivals snapshot into persistent hop tracks.
 * Mutates `tracks`. Vehicles that disappear from the feed are dropped.
 * Stale "due" rows (TTS ≈ 0 with no hop change) are evicted.
 */
export const ingestVehicleHops = ({
  tracks,
  predictions,
  stationsById,
  polylines,
  graph,
  graphForLine,
  asOf,
  staleDueMs = STALE_DUE_MS,
  viscosity = DEFAULT_VEHICLE_VISCOSITY,
}: {
  tracks: Map<string, VehicleHopTrack>
  predictions: readonly RealtimePrediction[]
  stationsById: ReadonlyMap<string, StationCoord>
  polylines: readonly (LineString | RoutePolyline)[]
  graph?: HopGraph | null
  graphForLine?: (lineId: string) => HopGraph | null
  asOf: number
  staleDueMs?: number
  viscosity?: VehicleViscosityParams
}): VehiclePosition[] => {
  const seen = new Set<string>()
  const scopedLines = new Set<string>()
  const out: VehiclePosition[] = []

  for (const group of groupPredictions(predictions)) {
    const next = group.rows[0]
    if (!next?.naptanId) continue
    const nextStop = stationsById.get(next.naptanId)
    if (!nextStop) continue

    const key = vehicleTrackKey(group.lineId, group.vehicleId)
    seen.add(key)
    scopedLines.add(group.lineId)
    const hopGraph = graphForLine?.(group.lineId) ?? graph ?? null
    const ttsNext = next.timeToStation ?? 0
    const after = group.rows[1]
    const followingStop = after?.naptanId
      ? stationsById.get(after.naptanId)
      : undefined
    const destinationName = next.destinationName ?? next.towards ?? ""
    const prev = tracks.get(key)

    let track: VehicleHopTrack
    if (!prev) {
      track = seedTrack({
        lineId: group.lineId,
        vehicleId: group.vehicleId,
        toStationId: next.naptanId,
        nextStop,
        followingStop,
        timeToNextSec: ttsNext,
        destinationName,
        asOf,
        graph: hopGraph,
        polylines,
      })
    } else {
      const sameHop = hopGraph
        ? hopGraph.canonical(prev.toStationId) ===
          hopGraph.canonical(next.naptanId)
        : prev.toStationId === next.naptanId

      if (sameHop) {
        const hop = hopKmBetween({
          from: {
            lat: prev.nextStopLat,
            lon: prev.nextStopLon,
          },
          to: nextStop,
          fromId: prev.fromStationId,
          toId: next.naptanId,
          lineId: group.lineId,
          polylines,
          graph: hopGraph,
        })
        const coasted = coastRemaining(prev, asOf, group.lineId, viscosity)
        const fromEta = remainingFromEta(
          group.lineId,
          ttsNext,
          hop.hopKm,
          hop.hopMinutes
        )
        track = markArrival(
          {
            ...prev,
            remainingKm: Math.min(coasted, fromEta),
            lastSeenAsOf: asOf,
            destinationName,
            nextStopLat: nextStop.lat,
            nextStopLon: nextStop.lon,
            followingStopLat: followingStop?.lat,
            followingStopLon: followingStop?.lon,
            dueSinceMs:
              ttsNext <= DUE_TTS_SEC ? (prev.dueSinceMs ?? asOf) : undefined,
          },
          asOf
        )
      } else {
        const adjacent = hopGraph
          ? areAdjacent(hopGraph, prev.toStationId, next.naptanId)
          : true
        if (!adjacent) {
          const coasted = coastRemaining(prev, asOf, group.lineId, viscosity)
          track = markArrival(
            {
              ...prev,
              remainingKm: coasted,
              lastSeenAsOf: asOf,
            },
            asOf
          )
        } else if (stillDwelling(prev.arrivedAtMs, asOf, viscosity)) {
          track = markArrival(
            {
              ...prev,
              remainingKm: 0,
              lastSeenAsOf: asOf,
              arrivedAtMs: prev.arrivedAtMs ?? asOf,
            },
            asOf
          )
        } else {
          const fromCoord = {
            lat: prev.nextStopLat,
            lon: prev.nextStopLon,
          }
          const hop = hopKmBetween({
            from: fromCoord,
            to: nextStop,
            fromId: prev.toStationId,
            toId: next.naptanId,
            lineId: group.lineId,
            polylines,
            graph: hopGraph,
          })
          const hopKm =
            hop.hopKm ??
            hopLengthKm({
              from: fromCoord,
              to: nextStop,
              lineId: group.lineId,
              polylines,
              fromStopId: prev.toStationId,
              toStopId: next.naptanId,
              canonical: hopGraph?.canonical,
            })
          const fromEta = remainingFromEta(
            group.lineId,
            ttsNext,
            hopKm > 0 ? hopKm : undefined,
            hop.hopMinutes
          )
          const incoming = hopGraph
            ? uniqueIncoming(hopGraph, next.naptanId)
            : undefined
          track = {
            lineId: group.lineId,
            vehicleId: group.vehicleId,
            toStationId: next.naptanId,
            fromStationId: prev.toStationId,
            branchId: incoming?.branchId,
            remainingKm: hopKm > 0 ? Math.min(hopKm, fromEta) : fromEta,
            hopDurationSecEstimate: Math.max(ttsNext, 1),
            lastSeenAsOf: asOf,
            dueSinceMs: ttsNext <= DUE_TTS_SEC ? asOf : undefined,
            destinationName,
            nextStopLat: nextStop.lat,
            nextStopLon: nextStop.lon,
            followingStopLat: followingStop?.lat,
            followingStopLon: followingStop?.lon,
          }
        }
      }
    }
    track = markArrival(track, asOf)

    if (track.dueSinceMs != null && asOf - track.dueSinceMs >= staleDueMs) {
      tracks.delete(key)
      continue
    }

    tracks.set(key, track)
    const placed = placeTrack(track, polylines, hopGraph)
    out.push(toPosition(track, placed, ttsNext, asOf))
  }

  for (const key of tracks.keys()) {
    if (seen.has(key)) continue
    const lineId = key.slice(0, key.indexOf(":"))
    if (scopedLines.has(lineId)) tracks.delete(key)
  }

  return out
}

/** Re-place a hop-locked vehicle as remaining km drains since `asOf`. */
export const advanceHopPosition = (
  vehicle: VehiclePosition,
  nowMs: number,
  polylines: readonly (LineString | RoutePolyline)[],
  viscosity: VehicleViscosityParams = DEFAULT_VEHICLE_VISCOSITY
): VehiclePosition => {
  if (
    vehicle.asOf == null ||
    vehicle.nextStopLat == null ||
    vehicle.nextStopLon == null
  ) {
    return vehicle
  }
  if (stillDwelling(vehicle.arrivedAtMs, nowMs, viscosity)) {
    return {
      ...vehicle,
      lat: vehicle.nextStopLat,
      lon: vehicle.nextStopLon,
      remainingKm: 0,
    }
  }
  const elapsedSec = Math.max(0, (nowMs - vehicle.asOf) / 1000)
  const speed = vehicleSpeedMetersPerSec(vehicle.lineId)
  const turnRadians = pathTurnBetween({
    from: { lat: vehicle.lat, lon: vehicle.lon },
    to: { lat: vehicle.nextStopLat, lon: vehicle.nextStopLon },
    lineId: vehicle.lineId,
    polylines,
    fromStopId: vehicle.fromStopId,
    toStopId: vehicle.nextStopId,
    canonical: hopGraphForRailLine(vehicle.lineId).canonical,
  })
  const remainingKm =
    vehicle.remainingKm != null
      ? viscousDrainKm({
          remainingKm: vehicle.remainingKm,
          elapsedSec,
          speedMetersPerSec: speed,
          turnRadians,
          params: viscosity,
        }).remainingKm
      : viscousDrainKm({
          remainingKm:
            (speed * Math.max(0, vehicle.timeToNextStationSec)) / 1000,
          elapsedSec,
          speedMetersPerSec: speed,
          turnRadians,
          params: viscosity,
        }).remainingKm
  const ttsNext = Math.max(0, vehicle.timeToNextStationSec - elapsedSec)
  if (remainingKm <= 0 || ttsNext <= 0) {
    return {
      ...vehicle,
      lat: vehicle.nextStopLat,
      lon: vehicle.nextStopLon,
      remainingKm: 0,
      arrivedAtMs: vehicle.arrivedAtMs ?? nowMs,
    }
  }
  const followingStop =
    vehicle.followingStopLat != null && vehicle.followingStopLon != null
      ? { lat: vehicle.followingStopLat, lon: vehicle.followingStopLon }
      : undefined
  const placed = positionBehindStop({
    nextStop: { lat: vehicle.nextStopLat, lon: vehicle.nextStopLon },
    followingStop,
    remainingKm,
    lineId: vehicle.lineId,
    polylines,
    fromStopId: vehicle.fromStopId,
    toStopId: vehicle.nextStopId,
    canonical: hopGraphForRailLine(vehicle.lineId).canonical,
  })
  return {
    ...vehicle,
    lat: placed.lat,
    lon: placed.lon,
    bearingDeg: placed.bearingDeg,
    remainingKm,
  }
}

/**
 * Shared viscosity for live-vehicle coast / ease.
 * Curvature already stretches interpolation on bends. Station proximity
 * uses the same factor so a train slows into a stop and holds there
 * instead of sliding through onto the next hop.
 */
export type VehicleViscosityParams = {
  /** Multiplier on turn/π (the bend term). */
  curvatureWeight: number
  /** Distance from the next stop where station viscosity starts. */
  stationApproachKm: number
  /** Peak extra viscosity at the stop (0 = off). */
  stationWeight: number
  /** Hold at the arrived stop before interpolation starts the next hop. */
  dwellSec: number
}

/**
 * Tuned on a 49-frame / 61-vehicle Central trace (1 Hz capture, scored as
 * 15 requests/min). Station approach cut mean error 5.3 m → 3.6 m and
 * zeroed station overshoot. Dwell 0–28 s tied on that minute; 18 s is
 * kept so interpolation holds at the stop when the next hop appears.
 */
export const DEFAULT_VEHICLE_VISCOSITY: VehicleViscosityParams = {
  curvatureWeight: 0.6,
  stationApproachKm: 0.16,
  stationWeight: 2.4,
  dwellSec: 18,
}

const clamp01 = (n: number) => Math.min(1, Math.max(0, n))

/** 0 in open track, 1 at / past the stop. */
export const stationProximity = (
  remainingKm: number,
  approachKm: number
): number => {
  if (approachKm <= 0) return remainingKm <= 0 ? 1 : 0
  if (remainingKm <= 0) return 1
  return clamp01(1 - remainingKm / approachKm)
}

/**
 * ≥1. Same shape as the old curvature ease: 1 on open straight track,
 * rising on a bend and as remaining km enters the station approach.
 */
export const viscosityFactor = ({
  remainingKm,
  turnRadians = 0,
  params,
}: {
  remainingKm?: number
  turnRadians?: number
  params?: VehicleViscosityParams
}): number => {
  const spec = params ?? DEFAULT_VEHICLE_VISCOSITY
  const curve =
    Math.min(1.6, Math.max(0, turnRadians) / Math.PI) * spec.curvatureWeight
  const proximity = stationProximity(
    remainingKm ?? Number.POSITIVE_INFINITY,
    spec.stationApproachKm
  )
  const station = proximity * proximity * spec.stationWeight
  return 1 + Math.min(2.4, curve + station)
}

export const viscousDrainKm = ({
  remainingKm,
  elapsedSec,
  speedMetersPerSec,
  turnRadians = 0,
  params,
}: {
  remainingKm: number
  elapsedSec: number
  speedMetersPerSec: number
  turnRadians?: number
  params?: VehicleViscosityParams
}): { remainingKm: number; held: boolean } => {
  if (remainingKm <= 0 || elapsedSec <= 0) {
    return { remainingKm: Math.max(0, remainingKm), held: remainingKm <= 0 }
  }
  const factor = viscosityFactor({ remainingKm, turnRadians, params })
  const drained = (speedMetersPerSec * elapsedSec) / 1000 / factor
  const next = Math.max(0, remainingKm - drained)
  return { remainingKm: next, held: next <= 0 }
}

export const stillDwelling = (
  arrivedAtMs: number | undefined,
  nowMs: number,
  params?: VehicleViscosityParams
): boolean => {
  const dwellMs = (params ?? DEFAULT_VEHICLE_VISCOSITY).dwellSec * 1000
  if (dwellMs <= 0 || arrivedAtMs == null) return false
  return nowMs - arrivedAtMs < dwellMs
}

export type LineHopTimes = {
  lineId: string
  hops: Record<string, number>
  timedHopCount: number
}

export type LineHopTimesByLine = Record<string, LineHopTimes>

export type LineHopTimesSnapshot = {
  fetchedAt: string
  source: string
  lines: LineHopTimesByLine
}

type TimetableInterval = {
  stopId?: string
  timeToArrival?: number
}

export type TimetableHopSource = {
  timetable?: {
    departureStopId?: string
    routes?: {
      stationIntervals?: {
        intervals?: TimetableInterval[]
      }[]
    }[]
  }
}

export const undirectedHopKey = (left: string, right: string): string =>
  left < right ? `${left}|${right}` : `${right}|${left}`

const stripNodePrefix = (id: string): string =>
  id.startsWith("s:") ? id.slice(2) : id

const median = (values: readonly number[]): number => {
  if (values.length === 0) return 0
  const sorted = [...values].sort((a, b) => a - b)
  const mid = Math.floor(sorted.length / 2)
  return sorted.length % 2 === 1
    ? sorted[mid]!
    : (sorted[mid - 1]! + sorted[mid]!) / 2
}

export const hopsFromTimetable = (
  response: TimetableHopSource
): Record<string, number> => {
  const samples = new Map<string, number[]>()
  const add = (from: string, to: string, minutes: number) => {
    if (!from || !to || from === to || minutes <= 0 || minutes > 20) return
    const key = undirectedHopKey(from, to)
    const list = samples.get(key) ?? []
    list.push(minutes)
    samples.set(key, list)
  }

  for (const route of response.timetable?.routes ?? []) {
    for (const interval of route.stationIntervals ?? []) {
      let previousId = response.timetable?.departureStopId
      let previousTime = 0
      for (const stop of interval.intervals ?? []) {
        if (!stop.stopId || stop.timeToArrival == null) continue
        if (previousId) {
          add(previousId, stop.stopId, stop.timeToArrival - previousTime)
        }
        previousId = stop.stopId
        previousTime = stop.timeToArrival
      }
    }
  }

  return Object.fromEntries(
    [...samples].map(([key, values]) => [key, median(values)])
  )
}

export const mergeHopMinutes = (
  ...groups: readonly Record<string, number>[]
): Record<string, number> => {
  const samples = new Map<string, number[]>()
  for (const group of groups) {
    for (const [key, minutes] of Object.entries(group)) {
      const list = samples.get(key) ?? []
      list.push(minutes)
      samples.set(key, list)
    }
  }
  return Object.fromEntries(
    [...samples].map(([key, values]) => [key, median(values)])
  )
}

export const minutesForHop = (
  hops: Record<string, number> | undefined,
  fromId: string | undefined,
  toId: string | undefined,
  canonical: (id: string) => string = (id) => id
): number | undefined => {
  if (!hops || !fromId || !toId) return undefined
  const from = stripNodePrefix(fromId)
  const to = stripNodePrefix(toId)
  const keys = [
    undirectedHopKey(from, to),
    undirectedHopKey(canonical(from), canonical(to)),
  ]
  for (const key of keys) {
    const minutes = hops[key]
    if (minutes != null) return minutes
  }
  return undefined
}

export const edgeLengthsFromHopTimes = (
  edges: readonly { from: string; to: string }[],
  nodeStationId: ReadonlyMap<string, string | undefined>,
  hops: Record<string, number> | undefined,
  canonical: (id: string) => string = (id) => id
): { from: string; to: string; length?: number }[] => {
  const known = edges.flatMap((edge) => {
    const minutes = minutesForHop(
      hops,
      nodeStationId.get(edge.from),
      nodeStationId.get(edge.to),
      canonical
    )
    return minutes != null ? [minutes] : []
  })
  const fallback = median(known) || 1
  return edges.map((edge) => {
    const minutes =
      minutesForHop(
        hops,
        nodeStationId.get(edge.from),
        nodeStationId.get(edge.to),
        canonical
      ) ?? fallback
    return { from: edge.from, to: edge.to, length: minutes }
  })
}

import { LINE_STATION_SEQUENCES } from "tfl-ts"
import { formatStationName } from "@/lib/tfl/diagram-station"
import type { OrderedRouteLike } from "@/lib/tfl/week-ahead-status"
import { selectLongestOrderedRoute } from "@/lib/tfl/week-ahead-status"

export type LineNode = {
  stationId: string
}

export type LineEdge = {
  fromStationId: string
  toStationId: string
  branchId: string
  state?: "normal" | "out-of-use"
}

export type LineBranchMeta = {
  id: string
  name: string
}

export type LineTopology = {
  lineId: string
  nodes: LineNode[]
  edges: LineEdge[]
  /** Preferred spine for compact 1-row views (week-ahead). */
  primaryBranchId: string
  branches: LineBranchMeta[]
  /** Display names keyed by Naptan id (static builder fills this). */
  stationNames?: Readonly<Record<string, string>>
  /** Segment ids that participate in a cycle via `nextBranchIds`. */
  loopBranchIds?: readonly string[]
  /**
   * Longest inbound Regular ordered route (full end-to-end).
   * Layout uses this as the trunk when present.
   */
  trunkStationIds?: readonly string[]
}

export type StaticBranchSegment = {
  id: string
  numericId: number
  stationIds: readonly string[]
  nextIds: readonly string[]
  previousIds: readonly string[]
}

export type StaticSequenceBranch = {
  id: number
  direction: string
  serviceType: string
  nextBranchIds: readonly number[]
  previousBranchIds: readonly number[]
  stationIds: readonly string[]
}

export type StaticSequenceRoute = {
  name: string
  direction: string
  serviceType: string
  stationIds: readonly string[]
}

export type StaticSequence = {
  lineId: string
  lineName: string
  stations: readonly { id: string; name: string }[]
  branches: readonly StaticSequenceBranch[]
  orderedRoutes: readonly StaticSequenceRoute[]
}

export const staticSegmentId = (numericId: number): string =>
  `segment-${numericId}`

export const getStaticLineSequence = (
  lineId: string
): StaticSequence | null => {
  const sequence = (
    LINE_STATION_SEQUENCES as Record<string, StaticSequence | undefined>
  )[lineId]
  return sequence ?? null
}

const inboundRegularBranches = (
  sequence: StaticSequence
): StaticSequenceBranch[] =>
  sequence.branches.filter(
    (branch) =>
      branch.direction === "inbound" &&
      branch.serviceType === "Regular" &&
      branch.stationIds.length >= 2
  )

const inboundRegularRoutes = (
  sequence: StaticSequence
): StaticSequenceRoute[] =>
  sequence.orderedRoutes.filter(
    (route) =>
      route.direction === "inbound" &&
      route.serviceType === "Regular" &&
      route.stationIds.length >= 2
  )

const detectLoopSegmentIds = (
  segments: readonly StaticSequenceBranch[]
): string[] => {
  const byId = new Map(segments.map((segment) => [segment.id, segment]))
  const loops = new Set<string>()

  for (const start of segments) {
    const seen = new Set<number>()
    const stack = [...start.nextBranchIds]
    while (stack.length > 0) {
      const nextId = stack.pop()!
      if (nextId === start.id) {
        loops.add(staticSegmentId(start.id))
        break
      }
      if (seen.has(nextId)) continue
      seen.add(nextId)
      const next = byId.get(nextId)
      if (!next) continue
      stack.push(...next.nextBranchIds)
    }
  }

  return [...loops]
}

/**
 * Lines whose inbound Regular sequence has more than one branch segment.
 * Simple corridors (Victoria, Bakerloo, …) are excluded.
 */
export const listBranchedLineIds = (): string[] => {
  const ids: string[] = []
  for (const sequence of Object.values(
    LINE_STATION_SEQUENCES
  ) as StaticSequence[]) {
    if (inboundRegularBranches(sequence).length > 1) {
      ids.push(sequence.lineId)
    }
  }
  return ids.sort((a, b) => a.localeCompare(b))
}

export const staticBranchSegments = (lineId: string): StaticBranchSegment[] => {
  const sequence = getStaticLineSequence(lineId)
  if (!sequence) return []
  return inboundRegularBranches(sequence).map((branch) => ({
    id: staticSegmentId(branch.id),
    numericId: branch.id,
    stationIds: branch.stationIds,
    nextIds: branch.nextBranchIds.map(staticSegmentId),
    previousIds: branch.previousBranchIds.map(staticSegmentId),
  }))
}

const slugifyBranch = (name: string, index: number): string => {
  const base = name
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "")
    .slice(0, 48)
  return base || `branch-${index + 1}`
}

const stationNameMap = (sequence: StaticSequence): Record<string, string> => {
  const names: Record<string, string> = {}
  for (const stop of sequence.stations) {
    names[stop.id] = formatStationName(stop.name)
  }
  return names
}

/**
 * Build a branched topology from tfl-ts `LINE_STATION_SEQUENCES` branch
 * segments (`nextBranchIds` / `previousBranchIds`). Inbound Regular only.
 */
export const buildLineTopologyFromStaticBranches = (
  lineId: string
): LineTopology | null => {
  const sequence = getStaticLineSequence(lineId)
  if (!sequence) return null

  const segments = inboundRegularBranches(sequence)
  if (segments.length === 0) return null

  const names = stationNameMap(sequence)
  const nodeIds = new Set<string>()
  const edgeKeys = new Set<string>()
  const edges: LineEdge[] = []
  const branches: LineBranchMeta[] = []

  for (const segment of segments) {
    const branchId = staticSegmentId(segment.id)
    const first = names[segment.stationIds[0]!] ?? segment.stationIds[0]!
    const last =
      names[segment.stationIds[segment.stationIds.length - 1]!] ??
      segment.stationIds[segment.stationIds.length - 1]!
    branches.push({
      id: branchId,
      name: first === last ? first : `${first} → ${last}`,
    })

    for (const id of segment.stationIds) nodeIds.add(id)
    for (let i = 0; i < segment.stationIds.length - 1; i += 1) {
      const from = segment.stationIds[i]!
      const to = segment.stationIds[i + 1]!
      const key = `${branchId}:${from}→${to}`
      if (edgeKeys.has(key)) continue
      edgeKeys.add(key)
      edges.push({ fromStationId: from, toStationId: to, branchId })
    }
  }

  const routes = inboundRegularRoutes(sequence)
  const longest = selectLongestOrderedRoute(
    routes.map((route) => ({
      name: route.name,
      naptanIds: [...route.stationIds],
      serviceType: route.serviceType,
    }))
  )
  const trunkStationIds = longest?.naptanIds ?? segments[0]!.stationIds
  const primary = [...segments].sort(
    (a, b) => b.stationIds.length - a.stationIds.length
  )[0]!

  return {
    lineId: sequence.lineId,
    nodes: [...nodeIds].map((stationId) => ({ stationId })),
    edges,
    primaryBranchId: staticSegmentId(primary.id),
    branches,
    stationNames: names,
    loopBranchIds: detectLoopSegmentIds(segments),
    trunkStationIds: [...trunkStationIds],
  }
}

/**
 * Build a branched topology from TfL orderedLineRoutes.
 * Each route becomes a branch; shared consecutive pairs share geometry.
 */
export const buildLineTopologyFromOrderedRoutes = (
  lineId: string,
  routes: OrderedRouteLike[] | null | undefined
): LineTopology | null => {
  if (!routes?.length) return null

  const usable = routes.filter((r) => (r.naptanIds?.length ?? 0) >= 2)
  if (usable.length === 0) return null

  const primary = selectLongestOrderedRoute(usable)
  const nodeIds = new Set<string>()
  const edgeKeys = new Set<string>()
  const edges: LineEdge[] = []
  const branches: LineBranchMeta[] = []

  usable.forEach((route, index) => {
    const ids = route.naptanIds ?? []
    const branchId = slugifyBranch(route.name ?? `route-${index + 1}`, index)
    branches.push({
      id: branchId,
      name: route.name?.trim() || `Branch ${index + 1}`,
    })

    for (const id of ids) nodeIds.add(id)
    for (let i = 0; i < ids.length - 1; i += 1) {
      const from = ids[i]!
      const to = ids[i + 1]!
      const key = `${branchId}:${from}→${to}`
      if (edgeKeys.has(key)) continue
      edgeKeys.add(key)
      edges.push({ fromStationId: from, toStationId: to, branchId })
    }
  })

  const primaryIndex = primary ? usable.indexOf(primary) : 0
  const primaryBranchId =
    primaryIndex >= 0
      ? slugifyBranch(
          usable[primaryIndex]?.name ?? `route-${primaryIndex + 1}`,
          primaryIndex
        )
      : branches[0]!.id

  return {
    lineId,
    nodes: [...nodeIds].map((stationId) => ({ stationId })),
    edges,
    primaryBranchId,
    branches,
  }
}

/** Ordered station ids for one branch (walk edges of that branchId). */
export const branchStationIds = (
  topology: LineTopology,
  branchId: string
): string[] => {
  const branchEdges = topology.edges.filter((e) => e.branchId === branchId)
  if (branchEdges.length === 0) return []

  const outgoing = new Map<string, string>()
  const inbound = new Set<string>()
  for (const edge of branchEdges) {
    outgoing.set(edge.fromStationId, edge.toStationId)
    inbound.add(edge.toStationId)
  }

  let start =
    branchEdges.find((e) => !inbound.has(e.fromStationId))?.fromStationId ??
    branchEdges[0]!.fromStationId

  const ordered: string[] = [start]
  const seen = new Set([start])
  while (outgoing.has(start)) {
    const next = outgoing.get(start)!
    if (seen.has(next)) break
    ordered.push(next)
    seen.add(next)
    start = next
  }
  return ordered
}

/** All station ids present in the topology (all branches). */
export const topologyStationIds = (topology: LineTopology): string[] =>
  topology.nodes.map((n) => n.stationId)

/**
 * Compact week-ahead spine: primary branch order, falling back to longest.
 */
export const primarySpineIds = (topology: LineTopology): string[] => {
  const primary = branchStationIds(topology, topology.primaryBranchId)
  if (primary.length >= 2) return primary

  let best: string[] = []
  for (const branch of topology.branches) {
    const ids = branchStationIds(topology, branch.id)
    if (ids.length > best.length) best = ids
  }
  return best
}

export type DiagramConnection = {
  id: string
  name: string
  /** Hex colour for flag box; defaults to muted if omitted. */
  color?: string
  /** When true, use corporate blue text (Circle / H&C / W&C). */
  darkText?: boolean
}

export type DiagramStation = {
  id: string
  name: string
  /** Show interchange ring instead of a tick. */
  interchange?: boolean
  /** Optional connecting-line flag boxes (Tube / TfL modes — not National Rail). */
  connections?: DiagramConnection[]
  /**
   * National Rail interchange — rendered as the NR pictogram beside the name,
   * not as a §9 text flag.
   */
  nationalRail?: boolean
}

/** Adjacent route segment state for horizontal diagrams. */
export type DiagramSegmentState = "normal" | "out-of-use"

export type DiagramSegment = {
  fromStationId: string
  toStationId: string
  state: DiagramSegmentState
}

/**
 * Parentheticals that disambiguate which stop / line — strip these.
 * Keep place-name parentheses such as Kensington (Olympia).
 */
const LINE_DISAMBIGUATION_PARENS =
  /\s*\((?:[^)]*\b(?:Line|Lines|Bakerloo|Central|Circle|District|Piccadilly|Northern|Victoria|Jubilee|Metropolitan|Elizabeth|H&C|Dist|Picc|London)\b[^)]*)\)/gi

/** Short display name for diagrams (drop common TfL suffixes + line brackets). */
export const formatStationName = (name: string): string => {
  const raw = typeof name === "string" ? name : name == null ? "" : String(name)
  let next = raw
    .replace(/\s+Underground Station$/i, "")
    .replace(/-Underground(?:\s+Station)?$/i, "")
    .replace(/\s+DLR Station$/i, "")
    .replace(/\s+Rail Station$/i, "")
    .replace(/\s+Tram (?:Stop|Station)$/i, "")
    .replace(/\s+Station$/i, "")
    .trim()

  next = next.replace(LINE_DISAMBIGUATION_PARENS, "").trim()

  // Heathrow Terminals 2 & 3 → 2&3 (no spaces around &)
  next = next.replace(/(\d+)\s*&\s*(\d+)/g, "$1&$2")

  return next.replace(/\s+/g, " ").trim()
}

export const isLikelyInterchange = (stop: {
  lines?: { id?: string | null }[] | null
  modes?: string[] | null
}): boolean => {
  const lineCount = stop.lines?.filter((l) => l.id).length ?? 0
  if (lineCount > 1) return true
  const modes = stop.modes?.filter(Boolean) ?? []
  return modes.length > 1
}

/**
 * Pure helpers for the homepage "This week ahead" line status view.
 * Structured TfL fields only — no NLP / regex on disruption prose.
 */

import type { DiagramSegment } from "@/lib/tfl/diagram-station"
import { validityOverlapsDay } from "@/lib/tfl/london-dates"

/** Homepage line order (TfL line IDs). */
export const WEEK_AHEAD_LINE_IDS = [
  "waterloo-city",
  "bakerloo",
  "central",
  "jubilee",
  "northern",
  "piccadilly",
  "district",
  "victoria",
  "circle",
  "hammersmith-city",
  "metropolitan",
  "elizabeth",
  "dlr",
  "liberty",
  "lioness",
  "mildmay",
  "suffragette",
  "weaver",
  "windrush",
  "tram",
] as const

export type WeekAheadLineId = (typeof WEEK_AHEAD_LINE_IDS)[number]

export type OrderedRouteLike = {
  name?: string
  naptanIds?: string[]
  serviceType?: string
}

/**
 * Pick the longest usable orderedLineRoute as the displayed spine.
 * Isolated so branch-aware rendering can replace this later.
 */
export const selectLongestOrderedRoute = (
  routes: OrderedRouteLike[] | null | undefined
): OrderedRouteLike | null => {
  if (!routes?.length) return null
  let best: OrderedRouteLike | null = null
  let bestLen = 0
  for (const route of routes) {
    const len = route.naptanIds?.length ?? 0
    if (len > bestLen) {
      best = route
      bestLen = len
    }
  }
  return bestLen > 0 ? best : null
}

export type ServiceRenderKind =
  "good" | "delays" | "part-closure" | "full-closure" | "unmapped-closure"

export type LineStatusLike = {
  statusSeverity?: number
  statusSeverityDescription?: string
  validityPeriods?: { fromDate?: string; toDate?: string; isNow?: boolean }[]
  disruption?: {
    closureText?: string
    affectedRoutes?: AffectedRouteLike[]
    affectedStops?: StopLike[]
  }
}

export type AffectedRouteLike = {
  isEntireRouteSection?: boolean
  name?: string
  routeSectionNaptanEntrySequence?: {
    ordinal?: number
    stopPoint?: StopLike
  }[]
}

export type StopLike = {
  id?: string
  naptanId?: string
  stationNaptan?: string
}

const FULL_CLOSURE_DESCRIPTIONS = new Set([
  "closed",
  "suspended",
  "planned closure",
  "no service",
  "not running",
  "service closed",
])

const PART_CLOSURE_DESCRIPTIONS = new Set([
  "part closure",
  "part suspended",
  "part closed",
])

const DELAY_DESCRIPTIONS = new Set([
  "minor delays",
  "severe delays",
  "reduced service",
  "diverted",
  "change of frequency",
  "issues reported",
])

const FULL_CLOSURE_TEXTS = new Set([
  "plannedclosure",
  "fullclosure",
  "suspended",
  "closed",
  "noservice",
])

const PART_CLOSURE_TEXTS = new Set([
  "partclosure",
  "partclosed",
  "partsuspended",
])

const DELAY_TEXTS = new Set(["minordelays", "severedelays", "reducedservice"])

const normalizeToken = (value: string): string =>
  value.toLowerCase().replace(/[\s_-]+/g, "")

/**
 * Classify structured status into a render kind.
 * Delays keep the official colour; closures may alter geometry.
 */
export const classifyLineStatus = (
  status: LineStatusLike
): ServiceRenderKind => {
  const description = (status.statusSeverityDescription ?? "")
    .trim()
    .toLowerCase()
  const closureText = normalizeToken(status.disruption?.closureText ?? "")

  if (
    FULL_CLOSURE_DESCRIPTIONS.has(description) ||
    FULL_CLOSURE_TEXTS.has(closureText)
  ) {
    return "full-closure"
  }

  if (
    PART_CLOSURE_DESCRIPTIONS.has(description) ||
    PART_CLOSURE_TEXTS.has(closureText)
  ) {
    return "part-closure"
  }

  if (DELAY_DESCRIPTIONS.has(description) || DELAY_TEXTS.has(closureText)) {
    return "delays"
  }

  if (
    !description ||
    description === "good service" ||
    description === "no issues"
  ) {
    return "good"
  }

  // Bus Service / Special Service / Information — show label, don't invent geometry.
  const severity = status.statusSeverity ?? 10
  if (severity <= 4) return "full-closure"
  if (severity === 5 || severity === 11) return "part-closure"
  if (severity === 6 || severity === 9 || severity === 7) return "delays"
  if (severity >= 10) return "good"

  return "delays"
}

/** Collect stop IDs that may appear on a diagram spine. */
export const stopIdentityIds = (
  stop: StopLike | null | undefined
): string[] => {
  if (!stop) return []
  const ids = [stop.stationNaptan, stop.naptanId, stop.id]
    .map((id) => id?.trim())
    .filter((id): id is string => Boolean(id))
  return [...new Set(ids)]
}

export const extractAffectedStopIds = (status: LineStatusLike): string[] => {
  const ids: string[] = []

  for (const route of status.disruption?.affectedRoutes ?? []) {
    for (const entry of route.routeSectionNaptanEntrySequence ?? []) {
      ids.push(...stopIdentityIds(entry.stopPoint))
    }
  }

  for (const stop of status.disruption?.affectedStops ?? []) {
    ids.push(...stopIdentityIds(stop))
  }

  return [...new Set(ids)]
}

export type SpineMappingResult = {
  /** Adjacent pairs to mark out of use on the displayed spine */
  outOfUseRanges: { fromIndex: number; toIndex: number }[]
  /** True when structured data claimed a closure we could not place on the spine */
  unmappedClosure: boolean
  /** Station IDs at closure endpoints (for forced labels) */
  closureEndpointIds: string[]
}

/**
 * Map affected stop IDs onto an ordered spine.
 * IDs that do not appear on the spine are ignored for geometry (branch absent
 * from this compact view). Prefer passing `topologyStationIds` when checking
 * whether a closure is “known” on any branch — see `closureMapsToTopology`.
 * If none map, `unmappedClosure` is true — keep colour, show a status note.
 */
export const mapAffectedIdsToSpine = (
  spineIds: readonly string[],
  affectedIds: readonly string[],
  options?: { treatAsEntireRoute?: boolean }
): SpineMappingResult => {
  if (options?.treatAsEntireRoute) {
    if (spineIds.length < 2) {
      return {
        outOfUseRanges: [],
        unmappedClosure: false,
        closureEndpointIds: [],
      }
    }
    return {
      outOfUseRanges: [{ fromIndex: 0, toIndex: spineIds.length - 1 }],
      unmappedClosure: false,
      closureEndpointIds: [spineIds[0]!, spineIds[spineIds.length - 1]!],
    }
  }

  if (affectedIds.length === 0) {
    return { outOfUseRanges: [], unmappedClosure: true, closureEndpointIds: [] }
  }

  const indexById = new Map<string, number>()
  spineIds.forEach((id, index) => indexById.set(id, index))

  const matchedIndexes = [
    ...new Set(
      affectedIds
        .map((id) => indexById.get(id))
        .filter((index): index is number => index != null)
    ),
  ].sort((a, b) => a - b)

  if (matchedIndexes.length === 0) {
    return { outOfUseRanges: [], unmappedClosure: true, closureEndpointIds: [] }
  }

  // Contiguous union covering all matched spine stops (part closure section).
  const fromIndex = matchedIndexes[0]!
  const toIndex = matchedIndexes[matchedIndexes.length - 1]!

  return {
    outOfUseRanges: fromIndex < toIndex ? [{ fromIndex, toIndex }] : [],
    unmappedClosure: false,
    closureEndpointIds:
      fromIndex < toIndex
        ? [spineIds[fromIndex]!, spineIds[toIndex]!]
        : [spineIds[fromIndex]!],
  }
}

/**
 * True when any affected stop id appears anywhere in the line topology
 * (including non-primary branches). Use before marking a closure unmapped.
 */
export const closureMapsToTopology = (
  topologyStationIdSet: ReadonlySet<string>,
  affectedIds: readonly string[]
): boolean => affectedIds.some((id) => topologyStationIdSet.has(id))

/** Merge half-open station-index ranges into diagram segment states. */
export const rangesToSegments = (
  spineIds: readonly string[],
  ranges: readonly { fromIndex: number; toIndex: number }[]
): DiagramSegment[] => {
  if (spineIds.length < 2) return []

  const outOfUse = new Array(spineIds.length - 1).fill(false)
  for (const range of ranges) {
    for (let i = range.fromIndex; i < range.toIndex; i += 1) {
      if (i >= 0 && i < outOfUse.length) outOfUse[i] = true
    }
  }

  return outOfUse.map((isOut, i) => ({
    fromStationId: spineIds[i]!,
    toStationId: spineIds[i + 1]!,
    state: isOut ? ("out-of-use" as const) : ("normal" as const),
  }))
}

/**
 * Station IDs to grey for closed segment ranges.
 * Uses the all-adjacent-closed rule (far terminals of a part closure grey;
 * boundary stations that still have an open side stay coloured).
 */
export const rangesToStationOutOfUseIds = (
  spineIds: readonly string[],
  ranges: readonly { fromIndex: number; toIndex: number }[]
): string[] => {
  if (spineIds.length === 0 || ranges.length === 0) return []

  const segments = rangesToSegments(spineIds, ranges)
  const segmentStates = segments.map((segment) => segment.state)
  const flags = stationOutOfUseFlags(spineIds.length, segmentStates)
  return spineIds.filter((_, index) => flags[index])
}

/** Pure station flags from segment states (shared with diagram helpers). */
const stationOutOfUseFlags = (
  stationCount: number,
  segmentStates: readonly ("normal" | "out-of-use")[]
): boolean[] => {
  const out = new Array(stationCount).fill(false)
  if (stationCount === 0) return out

  for (let i = 0; i < stationCount; i += 1) {
    const hasLeft = i > 0
    const hasRight = i < segmentStates.length
    if (!hasLeft && !hasRight) continue

    const leftClosed = hasLeft && segmentStates[i - 1] === "out-of-use"
    const rightClosed = hasRight && segmentStates[i] === "out-of-use"

    if (hasLeft && hasRight) {
      out[i] = leftClosed && rightClosed
    } else if (hasLeft) {
      out[i] = leftClosed
    } else {
      out[i] = rightClosed
    }
  }

  return out
}

export type DayLineServiceState = {
  kind: ServiceRenderKind
  /** Status labels to show (structured descriptions only) */
  labels: string[]
  segments: DiagramSegment[]
  forceLabelIds: string[]
  /** Stations whose markers should use the out-of-use colour */
  stationOutOfUseIds: string[]
  /** Concise note when a closure could not be mapped onto the spine */
  note?: string
}

const emptyGoodState = (spineIds: readonly string[]): DayLineServiceState => ({
  kind: "good",
  labels: [],
  segments: rangesToSegments(spineIds, []),
  forceLabelIds: [],
  stationOutOfUseIds: [],
})

const statusesForDay = (
  statuses: LineStatusLike[],
  dayStartMs: number,
  dayEndMs: number
): LineStatusLike[] => {
  const overlapping = statuses.filter((status) => {
    const periods = status.validityPeriods ?? []
    if (periods.length === 0) {
      // Realtime "Good Service" rows often omit periods — treat as current-only.
      // For a future day, empty periods do not apply.
      return false
    }
    return periods.some((period) =>
      validityOverlapsDay(period, dayStartMs, dayEndMs)
    )
  })
  return overlapping
}

/**
 * Build render state for one line on one selected day from pre-fetched statuses.
 */
export const buildDayLineServiceState = (
  spineIds: readonly string[],
  statuses: LineStatusLike[] | null | undefined,
  dayStartMs: number,
  dayEndMs: number
): DayLineServiceState => {
  if (!statuses?.length) {
    return emptyGoodState(spineIds)
  }

  const active = statusesForDay(statuses, dayStartMs, dayEndMs)
  if (active.length === 0) {
    return emptyGoodState(spineIds)
  }

  const labels = [
    ...new Set(
      active
        .map((s) => s.statusSeverityDescription?.trim())
        .filter(
          (label): label is string =>
            typeof label === "string" &&
            label.length > 0 &&
            label.toLowerCase() !== "good service"
        )
    ),
  ]

  const kinds = active.map(classifyLineStatus)
  const hasFull = kinds.includes("full-closure")
  const hasPart = kinds.includes("part-closure")
  const hasDelays = kinds.includes("delays")

  if (hasFull) {
    const mapping = mapAffectedIdsToSpine(spineIds, [], {
      treatAsEntireRoute: true,
    })
    return {
      kind: "full-closure",
      labels,
      segments: rangesToSegments(spineIds, mapping.outOfUseRanges),
      forceLabelIds: mapping.closureEndpointIds,
      stationOutOfUseIds: rangesToStationOutOfUseIds(
        spineIds,
        mapping.outOfUseRanges
      ),
    }
  }

  if (hasPart) {
    const ranges: { fromIndex: number; toIndex: number }[] = []
    const forceLabelIds: string[] = []
    let unmapped = false

    for (const status of active) {
      if (classifyLineStatus(status) !== "part-closure") continue

      const entire = status.disruption?.affectedRoutes?.some(
        (route) => route.isEntireRouteSection
      )
      if (entire) {
        const mapping = mapAffectedIdsToSpine(spineIds, [], {
          treatAsEntireRoute: true,
        })
        ranges.push(...mapping.outOfUseRanges)
        forceLabelIds.push(...mapping.closureEndpointIds)
        continue
      }

      const affectedIds = extractAffectedStopIds(status)
      const mapping = mapAffectedIdsToSpine(spineIds, affectedIds)
      if (mapping.unmappedClosure) unmapped = true
      ranges.push(...mapping.outOfUseRanges)
      forceLabelIds.push(...mapping.closureEndpointIds)
    }

    if (ranges.length === 0 && unmapped) {
      return {
        kind: "unmapped-closure",
        labels,
        segments: rangesToSegments(spineIds, []),
        forceLabelIds: [],
        stationOutOfUseIds: [],
        note: "Closure not on displayed route",
      }
    }

    return {
      kind: ranges.length > 0 ? "part-closure" : hasDelays ? "delays" : "good",
      labels,
      segments: rangesToSegments(spineIds, ranges),
      forceLabelIds: [...new Set(forceLabelIds)],
      stationOutOfUseIds: rangesToStationOutOfUseIds(spineIds, ranges),
      note: unmapped ? "Some closures not on displayed route" : undefined,
    }
  }

  if (hasDelays || labels.length > 0) {
    return {
      kind: hasDelays ? "delays" : "good",
      labels,
      segments: rangesToSegments(spineIds, []),
      forceLabelIds: [],
      stationOutOfUseIds: [],
    }
  }

  return emptyGoodState(spineIds)
}

/** Europe/London calendar helpers — no fixed 24h day length. */

export const LONDON_TIME_ZONE = "Europe/London"

const londonDateFormatter = new Intl.DateTimeFormat("en-CA", {
  timeZone: LONDON_TIME_ZONE,
  year: "numeric",
  month: "2-digit",
  day: "2-digit",
})

const londonWeekdayFormatter = new Intl.DateTimeFormat("en-GB", {
  timeZone: LONDON_TIME_ZONE,
  weekday: "long",
})

const londonDayMonthFormatter = new Intl.DateTimeFormat("en-GB", {
  timeZone: LONDON_TIME_ZONE,
  day: "numeric",
  month: "short",
})

const londonPartsFormatter = new Intl.DateTimeFormat("en-GB", {
  timeZone: LONDON_TIME_ZONE,
  year: "numeric",
  month: "2-digit",
  day: "2-digit",
  hour: "2-digit",
  minute: "2-digit",
  second: "2-digit",
  hourCycle: "h23",
})

export type LondonDay = {
  /** YYYY-MM-DD in Europe/London */
  dateKey: string
  /** Inclusive start (UTC ms) of the London calendar day */
  startMs: number
  /** Exclusive end (UTC ms) of the London calendar day */
  endMs: number
  startIso: string
  endIso: string
  weekdayLong: string
  /** Short numeric date for control disambiguation, e.g. "9 Aug" */
  dayMonth: string
  label: "Today" | "Tomorrow" | string
}

const partsMap = (date: Date): Record<string, string> => {
  const out: Record<string, string> = {}
  for (const part of londonPartsFormatter.formatToParts(date)) {
    if (part.type !== "literal") out[part.type] = part.value
  }
  return out
}

/** Calendar date key (YYYY-MM-DD) for an instant in Europe/London. */
export const londonDateKey = (instant: Date = new Date()): string =>
  londonDateFormatter.format(instant)

/** Weekday name in Europe/London, e.g. "Saturday". Pass an explicit instant. */
export const londonWeekdayLong = (nowMs: number): string =>
  londonWeekdayFormatter.format(new Date(nowMs))

/**
 * UTC ms of Europe/London midnight for `dateKey` (YYYY-MM-DD).
 * Iteratively corrects for DST so day length is never assumed to be 24h.
 */
export const londonDayStartMs = (dateKey: string): number => {
  const year = Number(dateKey.slice(0, 4))
  const month = Number(dateKey.slice(5, 7))
  const day = Number(dateKey.slice(8, 10))
  if (!year || !month || !day) {
    throw new Error(`Invalid London date key: ${dateKey}`)
  }

  const desiredAsUtc = Date.UTC(year, month - 1, day, 0, 0, 0)
  let utc = desiredAsUtc

  for (let i = 0; i < 4; i += 1) {
    const parts = partsMap(new Date(utc))
    const localAsUtc = Date.UTC(
      Number(parts.year),
      Number(parts.month) - 1,
      Number(parts.day),
      Number(parts.hour),
      Number(parts.minute),
      Number(parts.second)
    )
    const delta = desiredAsUtc - localAsUtc
    if (delta === 0) break
    utc += delta
  }

  return utc
}

/** Add calendar days in Europe/London (DST-safe via midday probe). */
export const addLondonCalendarDays = (
  dateKey: string,
  days: number
): string => {
  const start = londonDayStartMs(dateKey)
  const probe = new Date(
    start + 12 * 60 * 60 * 1000 + days * 24 * 60 * 60 * 1000
  )
  return londonDateKey(probe)
}

/** Half-open [start, end) bounds for a London calendar day. */
export const londonDayBounds = (
  dateKey: string
): { startMs: number; endMs: number; startIso: string; endIso: string } => {
  const startMs = londonDayStartMs(dateKey)
  const nextKey = addLondonCalendarDays(dateKey, 1)
  const endMs = londonDayStartMs(nextKey)
  return {
    startMs,
    endMs,
    startIso: new Date(startMs).toISOString(),
    endIso: new Date(endMs).toISOString(),
  }
}

export type WeekAheadDayRange = {
  days: LondonDay[]
  /** Inclusive TfL dateRange.startDate (YYYY-MM-DD) */
  startDate: string
  /** Inclusive TfL dateRange.endDate (YYYY-MM-DD) — last displayed day */
  endDate: string
}

/**
 * Eight consecutive Europe/London calendar days starting today.
 * Day 0 Today, day 1 Tomorrow, days 2–7 full weekday names.
 */
export const buildWeekAheadDays = (
  now: Date = new Date()
): WeekAheadDayRange => {
  const todayKey = londonDateKey(now)
  const days: LondonDay[] = []

  for (let offset = 0; offset < 8; offset += 1) {
    const dateKey = addLondonCalendarDays(todayKey, offset)
    const bounds = londonDayBounds(dateKey)
    const midday = new Date(bounds.startMs + 12 * 60 * 60 * 1000)
    const weekdayLong = londonWeekdayFormatter.format(midday)
    const dayMonth = londonDayMonthFormatter.format(midday)
    const label =
      offset === 0 ? "Today" : offset === 1 ? "Tomorrow" : weekdayLong

    days.push({
      dateKey,
      startMs: bounds.startMs,
      endMs: bounds.endMs,
      startIso: bounds.startIso,
      endIso: bounds.endIso,
      weekdayLong,
      dayMonth,
      label,
    })
  }

  return {
    days,
    startDate: days[0]!.dateKey,
    endDate: days[7]!.dateKey,
  }
}

/**
 * Validity overlap for a selected half-open day:
 * period.fromDate < selectedDayEnd && period.toDate > selectedDayStart
 */
export const validityOverlapsDay = (
  period: { fromDate?: string; toDate?: string },
  dayStartMs: number,
  dayEndMs: number
): boolean => {
  if (!period.fromDate || !period.toDate) return false
  const fromMs = Date.parse(period.fromDate)
  const toMs = Date.parse(period.toDate)
  if (Number.isNaN(fromMs) || Number.isNaN(toMs)) return false
  return fromMs < dayEndMs && toMs > dayStartMs
}
